  /**
   * Interpreta valores numéricos admitiendo números directos, strings con símbolos de moneda,
   * puntos de miles colombianos (ej. '300.000', '40.000.000') y decimales.
   * Evita el fallo de parseFloat("300.000") -> 300.
   */
  function parseNumber(val) {
    if (val === null || val === undefined || val === '') return 0;
    if (typeof val === 'number') return Number.isFinite(val) ? val : 0;
    let str = String(val).trim();
    const isNegative = str.startsWith('-') || str.startsWith('−');
    str = str.replace(/[\$\u20AC\s]/g, '').replace(/COP/gi, '').replace(/[^\d.,]/g, '');
    if (!str) return 0;

    let n = 0;
    // Múltiples puntos: claramente separador de miles (ej. 40.000.000)
    if ((str.match(/\./g) || []).length > 1) {
      str = str.replace(/\./g, '').replace(',', '.');
      n = parseFloat(str);
    } else if ((str.match(/,/g) || []).length > 1) {
      // Múltiples comas: separador de miles formato anglosajón (ej. 40,000,000)
      str = str.replace(/,/g, '');
      n = parseFloat(str);
    } else if (str.includes('.') && str.includes(',')) {
      // Ambos presentes: el último determina si es decimal o mil
      const lastDot = str.lastIndexOf('.');
      const lastComma = str.lastIndexOf(',');
      if (lastDot > lastComma) {
        // Formato 1,200.50
        str = str.replace(/,/g, '');
      } else {
        // Formato 1.200,50
        str = str.replace(/\./g, '').replace(',', '.');
      }
      n = parseFloat(str);
    } else if (str.includes('.')) {
      const parts = str.split('.');
      // Si la parte derecha tiene exactamente 3 dígitos, en moneda colombiana es separador de miles (ej. 300.000)
      if (parts[1].length === 3 && parts[0].length >= 1) {
        str = str.replace(/\./g, '');
      }
      n = parseFloat(str);
    } else if (str.includes(',')) {
      const parts = str.split(',');
      if (parts[1].length === 3 && parts[0].length >= 1) {
        str = str.replace(/,/g, '');
      } else {
        str = str.replace(',', '.');
      }
      n = parseFloat(str);
    } else {
      n = parseFloat(str);
    }

    if (!Number.isFinite(n)) return 0;
    return isNegative ? -Math.abs(n) : n;
  }

  // =========================================================================
  // 2. FORMATEADORES ESTÁNDAR MULTIMONEDA
  // =========================================================================

  function formatCurrency(val, code = 'COP', includeCurrency = true) {
    if (typeof root !== 'undefined' && root.GlossCurrency && root.GlossCurrency.formatCurrency) {
      return root.GlossCurrency.formatCurrency(val, code, includeCurrency);
    }
    if (typeof require !== 'undefined') {
      try {
        const path = require('path');
        const currModule = require(path.resolve(__dirname, 'currency-picker.js'));
        if (currModule && currModule.formatCurrency) {
          return currModule.formatCurrency(val, code, includeCurrency);
        }
      } catch (e) {}
    }
    if (val === null || val === undefined || !Number.isFinite(val)) return '—';
    const num = Math.round(val);
    const sign = num < 0 ? '−' : '';
    const formatted = new Intl.NumberFormat('es-CO').format(Math.abs(num));
    return sign + '$' + formatted + (includeCurrency ? ' ' + code : '');
  }

  function formatCOP(val, includeCurrency = true) {
    return formatCurrency(val, 'COP', includeCurrency);
  }

  function formatPct(val, decimals = 1) {
    if (val === null || val === undefined || !Number.isFinite(val)) return '—%';
    return val.toFixed(decimals).replace('.', ',') + '%';
  }

  function formatDecimal(val, decimals = 2) {
    if (val === null || val === undefined || !Number.isFinite(val)) return '—';
    return val.toFixed(decimals).replace('.', ',');
  }

  function formatInteger(val) {
    if (val === null || val === undefined || !Number.isFinite(val)) return '0';
    return Math.round(val).toLocaleString('es-CO');
  }

  function formatDate(d = new Date()) {
    const months = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
    const day = d.getDate();
    const month = months[d.getMonth()];
    const year = d.getFullYear();
    return `${day} de ${month} de ${year}`;
  }

  function formatDateShort(d = new Date()) {
    const day = String(d.getDate()).padStart(2, '0');
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const year = d.getFullYear();
    return `${day}/${month}/${year}`;
  }

  function formatDateIso(d = new Date()) {
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  }

  function buildFilename(toolKey, businessName, date = new Date()) {
    const dateStr = formatDateIso(date);
    const cleanName = (businessName || 'General')
      .trim()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-zA-Z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');
    const safeName = cleanName || 'General';
    return `Gloss-Growth_${toolKey}_${safeName}_${dateStr}.pdf`;
  }

