  function drawKpiGrid(doc, y, kpis) {
    const cardW = 42;
    const cardH = 17;
    const gap = 4;
    kpis.forEach((kpi, idx) => {
      const x = 15 + idx * (cardW + gap);
      doc.setFillColor(...C_CREAM_BG);
      doc.setDrawColor(...C_CREAM_BORDER);
      doc.setLineWidth(0.3);
      doc.roundedRect(x, y, cardW, cardH, 1.5, 1.5, 'FD');

      // Title
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(6.3);
      doc.setTextColor(...C_BURGUNDY);
      doc.text(kpi.label.toUpperCase(), x + 3, y + 5);

      // Value
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(10);
      doc.setTextColor(...C_CHARCOAL);
      doc.text(kpi.value, x + 3, y + 11.5);

      // Subtitle
      if (kpi.sub) {
        doc.setFont('helvetica', 'normal');
        doc.setFontSize(5.8);
        doc.setTextColor(...C_MUTED);
        doc.text(kpi.sub, x + 3, y + 15);
      }
    });
    return y + cardH + 5;
  }

  function drawSectionCallout(doc, curY, title, items) {
    if (title) {
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(8.5);
      doc.setTextColor(...C_CHARCOAL);
      doc.text(title, 15, curY + 2);
      curY += 4.5;
    }

    const normalizedItems = Array.isArray(items)
      ? items
      : (typeof items === 'string' ? [{ label: '', text: items }] : (items ? [items] : []));
    const validItems = normalizedItems.filter(Boolean);
    if (validItems.length === 0) {
      return curY;
    }

    const parsed = validItems.map(it => {
      const label = it.label || '';
      const text = it.text || '—';
      const splitText = doc.splitTextToSize(text, 172);
      return { label, splitText };
    });

    let contentHeight = 0;
    parsed.forEach((it, idx) => {
      contentHeight += 3.2;
      contentHeight += it.splitText.length * 3.2;
      if (idx < parsed.length - 1) {
        contentHeight += 2.2;
      }
    });

    const boxH = Math.max(22, contentHeight + 6);

    doc.setFillColor(...C_CREAM_BG);
    doc.setDrawColor(...C_CREAM_BORDER);
    doc.setLineWidth(0.3);
    doc.roundedRect(15, curY, 180, boxH, 1.5, 1.5, 'FD');

    let itemY = curY + 3.8;
    parsed.forEach((it, idx) => {
      if (it.label) {
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(6.8);
        doc.setTextColor(...C_BURGUNDY);
        doc.text(it.label, 19, itemY);
        itemY += 3.2;
      }

      doc.setFont('helvetica', 'normal');
      doc.setFontSize(6.5);
      doc.setTextColor(...C_CHARCOAL);
      doc.text(it.splitText, 19, itemY);
      itemY += it.splitText.length * 3.2;

      if (idx < parsed.length - 1) {
        itemY += 2.2;
      }
    });

    return curY + boxH + 4;
  }

  function saveOrOutput(doc, filename) {
    if (typeof window !== 'undefined' && doc.save) {
      doc.save(filename);
      return true;
    }
    return doc.output('arraybuffer');
  }

  // =========================================================================
  // 6. GENERADOR PDF: CAPACIDAD INSTALADA Y OCUPACIÓN
  // =========================================================================

  function generateCapacidadPdf(data = {}) {
    const doc = createPdfDoc();
    const bName = data.businessName ? data.businessName.trim() : 'Tu Clínica o Spa';
    const dateObj = data.date || new Date();
    const dateStr = formatDate(dateObj);
    const filename = buildFilename('Capacidad-Instalada', bName, dateObj);
    const res = data.result || {};
    const maxRev = res.maxRevenue || res.maxTheoreticalRevenue || 0;
    const targetRev = res.targetRevenue || (res.goal ? res.goal.targetRevenue : 0);
    const targetNeeded = res.targetAppointmentsNeeded || (res.goal ? res.goal.neededAppointments : 0);
    const targetAdd = res.targetAppointmentsAdditional || (res.goal ? res.goal.additionalAppointmentsNeeded : 0);
    const targetOcc = res.targetOccupancyReq || (res.goal ? res.goal.requiredOccupancy : 0);
    const isFeasible = res.isTargetFeasible !== undefined ? res.isTargetFeasible : (res.goal ? !res.goal.isExceedingCapacity : true);

    const cur = data.currency || (typeof root !== 'undefined' && root.GlossCurrency ? root.GlossCurrency.getSelectedCurrency() : 'COP');
    const fmt = (v) => formatCurrency(v, cur);

    drawPdfHeader(doc, 'Análisis de Capacidad Instalada y Ocupación', bName, dateStr, 'Evaluación operativa mensual y facturación potencial', cur);

    let curY = 41;

    // 4 Main KPIs
    curY = drawKpiGrid(doc, curY, [
      { label: 'Capacidad mensual', value: `${formatInteger(res.monthlyCapacity)} citas`, sub: 'Máximo teórico de citas' },
      { label: 'Ocupación actual', value: formatPct(res.occupancyRate), sub: 'Aprovechamiento de capacidad' },
      { label: 'Capacidad disponible', value: `${formatInteger(res.availableAppointments)} citas`, sub: 'Espacios de atención vacíos' },
      { label: 'Facturación estimada', value: fmt(res.currentRevenue), sub: 'Según citas atendidas' }
    ]);

    // Parámetros declarados
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...C_CHARCOAL);
    doc.text('1. PARÁMETROS OPERATIVOS DECLARADOS', 15, curY + 2);
    curY += 4.5;

    const col1 = [
      ['Profesionales operativos:', `${formatInteger(res.P)} profesional(es)`],
      ['Espacios o cabinas:', res.noCabinLimit ? 'Sin límite de cabinas' : `${formatInteger(res.C)} cabina(s)`],
      ['Horas diarias de atención:', `${formatDecimal(res.H, 1)} h/día efectivas`],
      ['Días de atención al mes:', `${formatInteger(res.D)} días/mes`]
    ];
    const col2 = [
      ['Duración total por cita:', `${formatInteger(res.T)} minutos (con preparación)`],
      ['Personal requerido por cita:', `${formatInteger(res.R)} profesional(es)`],
      ['Citas completadas en el mes:', `${formatInteger(res.A)} citas atendidas`],
      ['Ingreso promedio por cita:', fmt(res.V)],
      ['Facturación máxima mensual:', fmt(maxRev)]
    ];

    const maxRows = Math.max(col1.length, col2.length);
    const rowH = 4.6;
    doc.setFillColor(...C_CREAM_BG);
    doc.setDrawColor(...C_CREAM_BORDER);
    doc.setLineWidth(0.2);
    doc.roundedRect(15, curY, 180, maxRows * rowH + 2.5, 1, 1, 'FD');

    for (let i = 0; i < maxRows; i++) {
      const itemY = curY + 3.8 + i * rowH;
      if (col1[i]) {
        doc.setFont('helvetica', 'normal');
        doc.setFontSize(7);
        doc.setTextColor(...C_MUTED);
        doc.text(col1[i][0], 18, itemY);
        doc.setFont('helvetica', 'bold');
        doc.setTextColor(...C_CHARCOAL);
        doc.text(col1[i][1], 62, itemY);
      }
      if (col2[i]) {
        doc.setFont('helvetica', 'normal');
        doc.setFontSize(7);
        doc.setTextColor(...C_MUTED);
        doc.text(col2[i][0], 108, itemY);
        doc.setFont('helvetica', 'bold');
        doc.setTextColor(...C_CHARCOAL);
        doc.text(col2[i][1], 155, itemY);
      }
    }
    curY += maxRows * rowH + 6.5;

    // Meta de facturación (si aplica)
    if (targetRev > 0) {
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(8.5);
      doc.setTextColor(...C_CHARCOAL);
      doc.text('2. ANÁLISIS DE VIABILIDAD DE META DE FACTURACIÓN', 15, curY);
      curY += 3.5;

      doc.setFillColor(...(isFeasible ? [240, 253, 244] : C_ALERT_BG));
      doc.setDrawColor(...(isFeasible ? [134, 239, 172] : C_ALERT_BORDER));
      doc.setLineWidth(0.3);
      doc.roundedRect(15, curY, 180, 16, 1.5, 1.5, 'FD');

      doc.setFont('helvetica', 'bold');
      doc.setFontSize(7.8);
      doc.setTextColor(...(isFeasible ? C_SUCCESS : C_ALERT_RED));
      doc.text(`Meta mensual: ${fmt(targetRev)}  |  Citas necesarias: ${formatInteger(targetNeeded)}  |  Ocupación requerida: ${formatPct(targetOcc)}`, 19, curY + 5.5);

      doc.setFont('helvetica', 'normal');
      doc.setFontSize(6.8);
      doc.setTextColor(...C_CHARCOAL);
      if (isFeasible) {
        doc.text(`Resultado operativo: Meta viable dentro de la capacidad instalada declarada (${formatInteger(res.monthlyCapacity)} citas). Requiere añadir ${formatInteger(targetAdd)} citas adicionales.`, 19, curY + 10.5);
      } else {
        doc.text(`Resultado operativo: Meta superior a la capacidad declarada del centro (${formatInteger(res.monthlyCapacity)} citas mensuales). Para alcanzar esta facturación es`, 19, curY + 9.5);
        doc.text('físicamente indispensable incorporar más profesionales, habilitar cabinas adicionales o elevar el ticket promedio por atención.', 19, curY + 13);
      }
      curY += 20.5;
    }

    // Escenarios de ocupación
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...C_CHARCOAL);
    doc.text('3. ESCENARIOS DE CRECIMIENTO EN OCUPACIÓN', 15, curY);
    curY += 3.5;

    // Table Header
    doc.setFillColor(...C_BURGUNDY);
    doc.rect(15, curY, 180, 4.8, 'F');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(6.8);
    doc.setTextColor(...C_WHITE);
    doc.text('Nivel de Ocupación', 18, curY + 3.4);
    doc.text('Citas Objetivo', 65, curY + 3.4);
    doc.text('Citas Adicionales', 95, curY + 3.4);
    doc.text('Facturación Estimada', 130, curY + 3.4);
    doc.text('Facturación Adicional', 165, curY + 3.4);
    curY += 4.8;

    const scenarios = res.scenarios || [];
    scenarios.forEach((s, idx) => {
      const isAlt = idx % 2 === 1;
      const tApts = s.targetApts !== undefined ? s.targetApts : s.targetAppointments;
      const aApts = s.addApts !== undefined ? s.addApts : s.additionalAppointments;
      const rev = s.revenue !== undefined ? s.revenue : s.targetRevenue;
      const aRev = s.addRevenue !== undefined ? s.addRevenue : s.additionalRevenue;

      doc.setFillColor(isAlt ? 249 : 255, isAlt ? 248 : 255, isAlt ? 246 : 255);
      doc.rect(15, curY, 180, 4.8, 'F');
      doc.setDrawColor(...C_CREAM_BORDER);
      doc.setLineWidth(0.15);
      doc.line(15, curY + 4.8, 195, curY + 4.8);

      doc.setFont('helvetica', s.isCustom ? 'bold' : 'normal');
      doc.setFontSize(6.8);
      doc.setTextColor(...C_CHARCOAL);
      doc.text(`Ocupación al ${s.pct}%${s.label ? ' (' + s.label + ')' : ''}`, 18, curY + 3.4);
      doc.text(`${formatInteger(tApts)} citas`, 65, curY + 3.4);
      doc.text(`${aApts >= 0 ? '+' : ''}${formatInteger(aApts)} citas`, 95, curY + 3.4);
      doc.text(fmt(rev), 130, curY + 3.4);

      doc.setFont('helvetica', 'bold');
      doc.setTextColor(...(aRev >= 0 ? C_BURGUNDY : C_ALERT_RED));
      doc.text(`${aRev >= 0 ? '+' : ''}${fmt(aRev)}`, 165, curY + 3.4);
      curY += 4.8;
    });
    curY += 4.5;

    // Interpretación Determinista
    if (res.interpretation) {
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(8.5);
      doc.setTextColor(...C_CHARCOAL);
      doc.text('4. INTERPRETACIÓN OPERATIVA Y RECOMENDACIÓN ESTRATÉGICA', 15, curY);
      curY += 3.5;

      doc.setFillColor(...C_CREAM_BG);
      doc.setDrawColor(...C_CREAM_BORDER);
      doc.setLineWidth(0.3);
      doc.roundedRect(15, curY, 180, 27, 1.5, 1.5, 'FD');

      const pts = [
        ['1. Diagnóstico de ocupación:', res.interpretation.fact || '—'],
        ['2. Capacidad disponible:', res.interpretation.state || res.interpretation.capacityState || '—'],
        ['3. Qué revisar:', res.interpretation.advice || '—']
      ];

      pts.forEach((pt, i) => {
        const ptY = curY + 3.5 + i * 7.8;
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(6.8);
        doc.setTextColor(...C_BURGUNDY);
        doc.text(pt[0], 19, ptY);

        doc.setFont('helvetica', 'normal');
        doc.setTextColor(...C_CHARCOAL);
        // Split text if too wide
        const splitText = doc.splitTextToSize(pt[1], 170);
        doc.text(splitText[0] || '', 19, ptY + 3.4);
      });
      curY += 30;
    }

    // Nota metodológica
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(6.2);
    doc.setTextColor(...C_MUTED);
    doc.text('Nota metodológica: Informe generado automáticamente por el Centro de Recursos de Gloss & Growth (glossgrowthhq.com). Este simulador aplica restricciones estrictas', 15, curY);
    doc.text('por jornada diaria (no traslada minutos sobrantes entre días). Cifras de facturación brutas basadas en el ingreso promedio declarado por atención, sin deducir costos.', 15, curY + 3);

    // Footer
    drawPdfFooter(doc, 1, 1);

    return saveOrOutput(doc, filename);
  }

  // =========================================================================
  // 7. GENERADOR PDF: RENTABILIDAD POR TRATAMIENTO
  // =========================================================================

  function generateTratamientoPdf(data = {}) {
    const doc = createPdfDoc();
    const bName = data.businessName ? data.businessName.trim() : 'Tu Clínica o Spa';
    const dateObj = data.date || new Date();
    const dateStr = formatDate(dateObj);
    const filename = buildFilename('Rentabilidad', bName, dateObj);
    const cur = data.currency || (typeof root !== 'undefined' && root.GlossCurrency ? root.GlossCurrency.getSelectedCurrency() : 'COP');
    const fmt = (v) => formatCurrency(v, cur);
    const t = data.treatment || {};

    drawPdfHeader(doc, 'Análisis de Rentabilidad por Tratamiento', bName, dateStr, 'Evaluación de costos directos, margen de contribución y utilidad', cur);

    let curY = 41;

    // 4 Key KPIs
    curY = drawKpiGrid(doc, curY, [
      { label: 'Margen contribución', value: fmt(t.margenContribucion), sub: `${formatPct(t.margenContribucionPct)} del precio` },
      { label: 'Costos variables', value: fmt(t.costoVariableTotal), sub: 'Insumos + honorarios + com.' },
      { label: 'Resultado tras fijos', value: fmt(t.resultadoTrasFijos), sub: `${formatPct(t.margenTrasFijosPct)} tras fijos` },
      { label: 'Utilidad por hora', value: t.utilidadPorHora ? fmt(t.utilidadPorHora) : '—', sub: t.tiempoTotalMinutos ? `En ${t.tiempoTotalMinutos} min de atención` : 'Requiere tiempo > 0' }
    ]);

    // Desglose de Costos Unitarios
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...C_CHARCOAL);
    doc.text('1. ESTRUCTURA DE COSTOS Y MÁRGENES UNITARIOS', 15, curY + 2);
    curY += 4.5;

    const costItems = [
      ['Precio de venta al público (PVP):', fmt(t.precio), '100,0%'],
      ['Insumos y consumibles médicos directos:', fmt(t.insumosTotal), t.precio > 0 ? formatPct((t.insumosTotal / t.precio) * 100) : '—'],
      ['Honorarios profesionales por atención:', fmt(t.honorariosTotal), t.precio > 0 ? formatPct((t.honorariosTotal / t.precio) * 100) : '—'],
      ['Comisión pasarela / datáfono:', fmt(t.costoComision), t.precio > 0 ? formatPct((t.costoComision / t.precio) * 100) : '—'],
      ['TOTAL COSTOS VARIABLES DIRECTOS:', fmt(t.costoVariableTotal), formatPct(100 - t.margenContribucionPct)],
      ['MARGEN DE CONTRIBUCIÓN BRUTO:', fmt(t.margenContribucion), formatPct(t.margenContribucionPct)],
      ['Gastos fijos asignados por atención:', fmt(t.fijosTotal), t.precio > 0 ? formatPct((t.fijosTotal / t.precio) * 100) : '—'],
      ['RESULTADO TRAS COSTOS FIJOS ASIGNADOS:', fmt(t.resultadoTrasFijos), formatPct(t.margenTrasFijosPct)]
    ];

    doc.setFillColor(...C_BURGUNDY);
    doc.rect(15, curY, 180, 4.8, 'F');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(6.8);
    doc.setTextColor(...C_WHITE);
    doc.text('Concepto Financiero', 18, curY + 3.4);
    doc.text('Importe Unitario', 130, curY + 3.4);
    doc.text('% sobre Precio', 170, curY + 3.4);
    curY += 4.8;

    costItems.forEach((item, idx) => {
      const isTotal = idx === 4 || idx === 5 || idx === 7;
      const isAlt = idx % 2 === 1;
      doc.setFillColor(isTotal ? 250 : (isAlt ? 249 : 255), isTotal ? 248 : (isAlt ? 248 : 255), isTotal ? 242 : (isAlt ? 246 : 255));
      doc.rect(15, curY, 180, 4.6, 'F');
      doc.setDrawColor(...C_CREAM_BORDER);
      doc.setLineWidth(0.15);
      doc.line(15, curY + 4.6, 195, curY + 4.6);

      doc.setFont('helvetica', isTotal ? 'bold' : 'normal');
      doc.setFontSize(6.8);
      doc.setTextColor(...(isTotal ? C_BURGUNDY : C_CHARCOAL));
      doc.text(item[0], 18, curY + 3.2);
      doc.text(item[1], 130, curY + 3.2);
      doc.text(item[2], 170, curY + 3.2);
      curY += 4.6;
    });
    curY += 5;

    // Escenario Mensual Proyectado (si aplica)
    if (t.sesiones && t.sesiones > 0) {
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(8.5);
      doc.setTextColor(...C_CHARCOAL);
      doc.text('2. PROYECCIÓN MENSUAL SEGÚN VOLUMEN ESTIMADO', 15, curY);
      curY += 3.5;

      const monthlyItems = [
        ['Sesiones estimadas al mes:', `${formatInteger(t.sesiones)} atenciones`],
        ['Facturación mensual bruta:', fmt(t.ingresoMensual)],
        ['Costos variables directos totales:', fmt(t.costoVariableTotal * t.sesiones)],
        ['Gastos fijos asignados totales:', fmt(t.fijosTotal * t.sesiones)],
        ['Utilidad neta mensual estimada:', fmt(t.utilidadMensual)]
      ];

      doc.setFillColor(...C_CREAM_BG);
      doc.setDrawColor(...C_CREAM_BORDER);
      doc.setLineWidth(0.2);
      doc.roundedRect(15, curY, 180, 16, 1, 1, 'FD');

      monthlyItems.forEach((m, idx) => {
        const mX = 18 + (idx < 3 ? idx * 58 : (idx - 3) * 85);
        const mY = curY + (idx < 3 ? 4 : 11);
        doc.setFont('helvetica', 'normal');
        doc.setFontSize(6.5);
        doc.setTextColor(...C_MUTED);
        doc.text(m[0], mX, mY);
        doc.setFont('helvetica', 'bold');
        doc.setTextColor(...(idx === 4 ? C_BURGUNDY : C_CHARCOAL));
        doc.text(m[1], mX, mY + 3.5);
      });
      curY += 20;
    }

    // Interpretación Determinista
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...C_CHARCOAL);
    doc.text('3. INTERPRETACIÓN FINANCIERA PRUDENTE', 15, curY);
    curY += 3.5;

    doc.setFillColor(...C_CREAM_BG);
    doc.setDrawColor(...C_CREAM_BORDER);
    doc.setLineWidth(0.3);
    doc.roundedRect(15, curY, 180, 24, 1.5, 1.5, 'FD');

    const diagText = t.interpretacion || 'El margen de contribución directo cubre los costos variables obligatorios de cada sesión. Para una evaluación financiera rigurosa, no se debe considerar este resultado como utilidad neta libre hasta absorber la totalidad de los costos fijos globales de la clínica (arriendo, nómina administrativa, servicios y marketing).';
    const splitDiag = doc.splitTextToSize(diagText, 172);

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(7);
    doc.setTextColor(...C_BURGUNDY);
    doc.text('Criterio financiero de contribución:', 19, curY + 4.5);

    doc.setFont('helvetica', 'normal');
    doc.setTextColor(...C_CHARCOAL);
    doc.text(splitDiag, 19, curY + 8.5);

    curY += 28;

    // Nota metodológica
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(6.2);
    doc.setTextColor(...C_MUTED);
    doc.text('Nota metodológica: Informe emitido por el Centro de Recursos de Gloss & Growth (glossgrowthhq.com). Este reporte clasifica de manera estricta costos variables', 15, curY);
    doc.text('directos frente a fijos asignados. No sustituye la contabilidad fiscal del establecimiento, sino que provee una herramienta de fijación de precios y toma de decisiones.', 15, curY + 3);

    // Footer
    drawPdfFooter(doc, 1, 1);

    return saveOrOutput(doc, filename);
  }

  // =========================================================================
  // 8. GENERADOR PDF: ROAS Y RENTABILIDAD PUBLICITARIA
  // =========================================================================

  function generateRoasPdf(data = {}) {
    const doc = createPdfDoc();
    const bName = data.businessName ? data.businessName.trim() : 'Tu Clínica o Spa';
    const dateObj = data.date || new Date();
    const dateStr = formatDate(dateObj);
    const filename = buildFilename('ROAS', bName, dateObj);
    const cur = data.currency || (typeof root !== 'undefined' && root.GlossCurrency ? root.GlossCurrency.getSelectedCurrency() : 'COP');
    const fmt = (v) => formatCurrency(v, cur);
    const r = data.roas || {};

    drawPdfHeader(doc, 'Análisis de ROAS y Rentabilidad Publicitaria', bName, dateStr, r.isRealMode ? 'Modo Resultados Históricos Reales' : 'Modo Planificación y Punto de Equilibrio', cur);

    let curY = 41;

    // 4 Key KPIs
    curY = drawKpiGrid(doc, curY, [
      { label: 'ROAS equilibrio', value: `${formatDecimal(r.roasEquilibrio, 2)}x`, sub: 'Punto cero de beneficio' },
      { label: 'Facturación necesaria', value: fmt(r.facturacionEquilibrio), sub: 'Para no perder dinero' },
      { label: 'Ventas necesarias', value: `${formatInteger(r.ventasEquilibrio)} atenciones`, sub: 'Volumen mínimo de citas' },
      { label: 'Inversión marketing', value: fmt(r.inversionTotalMarketing), sub: 'Pauta + gestión + otros' }
    ]);

    // Parámetros de la Campaña y Servicio
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...C_CHARCOAL);
    doc.text('1. PARÁMETROS DE LA INVERSIÓN Y DEL SERVICIO', 15, curY + 2);
    curY += 4.5;

    const pCol1 = [
      ['Inversión directa en pauta (Ads):', fmt(r.adSpend)],
      ['Honorarios de gestión / agencia:', fmt(r.managementFee)],
      ['Otros costos de marketing:', fmt(r.otherCosts)],
      ['Período analizado:', r.periodo || 'Mensual (30 días)']
    ];
    const pCol2 = [
      ['Precio del servicio o ticket promedio:', fmt(r.ticketPrice)],
      ['Costo variable directo por venta:', fmt(r.unitVarCost)],
      ['Margen de contribución directo:', formatPct(r.margenContribucionPct)],
      ['Capacidad operativa declarada:', r.capacity ? `${r.capacity} cupos` : 'No declarada']
    ];

    const maxP = Math.max(pCol1.length, pCol2.length);
    const pRowH = 4.6;
    doc.setFillColor(...C_CREAM_BG);
    doc.setDrawColor(...C_CREAM_BORDER);
    doc.setLineWidth(0.2);
    doc.roundedRect(15, curY, 180, maxP * pRowH + 2.5, 1, 1, 'FD');

    for (let i = 0; i < maxP; i++) {
      const itemY = curY + 3.8 + i * pRowH;
      if (pCol1[i]) {
        doc.setFont('helvetica', 'normal');
        doc.setFontSize(7);
        doc.setTextColor(...C_MUTED);
        doc.text(pCol1[i][0], 18, itemY);
        doc.setFont('helvetica', 'bold');
        doc.setTextColor(...C_CHARCOAL);
        doc.text(pCol1[i][1], 62, itemY);
      }
      if (pCol2[i]) {
        doc.setFont('helvetica', 'normal');
        doc.setFontSize(7);
        doc.setTextColor(...C_MUTED);
        doc.text(pCol2[i][0], 108, itemY);
        doc.setFont('helvetica', 'bold');
        doc.setTextColor(...C_CHARCOAL);
        doc.text(pCol2[i][1], 155, itemY);
      }
    }
    curY += maxP * pRowH + 6.5;

    // Matriz de Sensibilidad de ROAS
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...C_CHARCOAL);
    doc.text('2. MATRIZ DE SENSIBILIDAD DE RENDIMIENTO (ROAS)', 15, curY);
    curY += 3.5;

    doc.setFillColor(...C_BURGUNDY);
    doc.rect(15, curY, 180, 4.8, 'F');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(6.8);
    doc.setTextColor(...C_WHITE);
    doc.text('Múltiplo ROAS', 18, curY + 3.4);
    doc.text('Facturación', 52, curY + 3.4);
    doc.text('Ventas Necesarias', 88, curY + 3.4);
    doc.text('Margen Bruto', 124, curY + 3.4);
    doc.text('Inversión Mkt', 154, curY + 3.4);
    doc.text('Resultado Neto', 178, curY + 3.4);
    curY += 4.8;

    const matrixRows = r.matrixSummary || [
      { roas: 1.5, ingreso: r.adSpend * 1.5, ventas: Math.ceil((r.adSpend * 1.5) / (r.ticketPrice || 1)), resultado: (r.adSpend * 1.5 * (r.margenContribucionPct / 100)) - r.inversionTotalMarketing },
      { roas: 2.0, ingreso: r.adSpend * 2.0, ventas: Math.ceil((r.adSpend * 2.0) / (r.ticketPrice || 1)), resultado: (r.adSpend * 2.0 * (r.margenContribucionPct / 100)) - r.inversionTotalMarketing },
      { roas: r.roasEquilibrio || 2.5, isBreakeven: true, ingreso: r.facturacionEquilibrio, ventas: r.ventasEquilibrio, resultado: 0 },
      { roas: 3.0, ingreso: r.adSpend * 3.0, ventas: Math.ceil((r.adSpend * 3.0) / (r.ticketPrice || 1)), resultado: (r.adSpend * 3.0 * (r.margenContribucionPct / 100)) - r.inversionTotalMarketing },
      { roas: 4.0, ingreso: r.adSpend * 4.0, ventas: Math.ceil((r.adSpend * 4.0) / (r.ticketPrice || 1)), resultado: (r.adSpend * 4.0 * (r.margenContribucionPct / 100)) - r.inversionTotalMarketing }
    ];

    matrixRows.forEach((m, idx) => {
      const isAlt = idx % 2 === 1;
      const isEq = m.isBreakeven;
      doc.setFillColor(isEq ? 254 : (isAlt ? 249 : 255), isEq ? 249 : (isAlt ? 248 : 255), isEq ? 231 : (isAlt ? 246 : 255));
      doc.rect(15, curY, 180, 4.6, 'F');
      doc.setDrawColor(...C_CREAM_BORDER);
      doc.setLineWidth(0.15);
      doc.line(15, curY + 4.6, 195, curY + 4.6);

      doc.setFont('helvetica', isEq ? 'bold' : 'normal');
      doc.setFontSize(6.8);
      doc.setTextColor(...(isEq ? C_BURGUNDY : C_CHARCOAL));
      doc.text(`${formatDecimal(m.roas, 2)}x${isEq ? ' [Equilibrio]' : ''}`, 18, curY + 3.2);
      doc.text(fmt(m.ingreso), 52, curY + 3.2);
      doc.text(`${formatInteger(m.ventas)} citas`, 88, curY + 3.2);
      doc.text(fmt(m.ingreso * (r.margenContribucionPct / 100)), 124, curY + 3.2);
      doc.text(fmt(r.inversionTotalMarketing), 154, curY + 3.2);

      const net = m.resultado;
      doc.setFont('helvetica', 'bold');
      doc.setTextColor(...(net > 0 ? C_SUCCESS : (net < 0 ? C_ALERT_RED : C_CHARCOAL)));
      doc.text(`${net > 0 ? '+' : ''}${fmt(net)}`, 178, curY + 3.2);
      curY += 4.6;
    });
    curY += 5;

    // Interpretación Determinista
    if (r.interpretation) {
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(8.5);
      doc.setTextColor(...C_CHARCOAL);
      doc.text('3. INTERPRETACIÓN ESTRATÉGICA DE LA INVERSIÓN', 15, curY);
      curY += 3.5;

      doc.setFillColor(...C_CREAM_BG);
      doc.setDrawColor(...C_CREAM_BORDER);
      doc.setLineWidth(0.3);
      doc.roundedRect(15, curY, 180, 27, 1.5, 1.5, 'FD');

      const pts = [
        ['1. Umbral matemático de equilibrio:', r.interpretation.fact || '—'],
        ['2. Diagnóstico operativo de absorción:', r.interpretation.meaning || '—'],
        ['3. Recomendación de asignación de presupuesto:', r.interpretation.recommendation || '—']
      ];

      pts.forEach((pt, i) => {
        const ptY = curY + 3.5 + i * 7.8;
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(6.8);
        doc.setTextColor(...C_BURGUNDY);
        doc.text(pt[0], 19, ptY);

        doc.setFont('helvetica', 'normal');
        doc.setTextColor(...C_CHARCOAL);
        const splitText = doc.splitTextToSize(pt[1], 170);
        doc.text(splitText[0] || '', 19, ptY + 3.4);
      });
      curY += 30;
    }

    // Nota metodológica
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(6.2);
    doc.setTextColor(...C_MUTED);
    doc.text('Nota metodológica: Informe emitido por el Centro de Recursos de Gloss & Growth (glossgrowthhq.com). El ROAS de equilibrio calcula el retorno publicitario', 15, curY);
    doc.text('mínimo para absorber tanto la pauta como los honorarios y costos variables directos. Los resultados reales dependerán de la tasa de cierre en WhatsApp y la tasa de asistencia.', 15, curY + 3);

    // Footer
    drawPdfFooter(doc, 1, 1);

    return saveOrOutput(doc, filename);
  }

