  function generatePromoClipboard(data) {
    const bName = data.businessName ? data.businessName.trim() : 'Tu Clínica o Spa';
    const dateStr = formatDateShort(data.date || new Date());
    const cur = data.currency || (typeof root !== 'undefined' && root.GlossCurrency ? root.GlossCurrency.getSelectedCurrency() : 'COP');
    const curInfo = typeof root !== 'undefined' && root.GlossCurrency ? root.GlossCurrency.getCurrency(cur) : { name: cur, symbol: '$' };
    const fmt = (v) => formatCurrency(v, cur);
    const p = data.promo || {};

    let lines = [
      'GLOSS & GROWTH',
      'SIMULACIÓN DE PRECIOS Y PROMOCIONES',
      '',
      'Negocio: ' + bName,
      'Tratamiento base: ' + (p.treatmentName || 'Tratamiento evaluado'),
      'Modalidad: ' + (p.modalityTitle || 'Promoción'),
      'Fecha: ' + dateStr,
      'Moneda: ' + curInfo.name + ' (' + cur + ')',
      '',
      'COMPARATIVA: TARIFA HABITUAL VS. PROMOCIÓN',
      '• Precio habitual de referencia: ' + fmt(p.regularPrice),
      '• Precio promocional / oferta: ' + fmt(p.promoPrice),
      '• Descuento / Ahorro ofrecido: ' + fmt(p.savings) + ' (' + formatPct(p.discountPct) + ')',
      '• Costos variables directos: ' + fmt(p.totalVarCost),
      '• Margen de contribución de la promoción: ' + fmt(p.contribution) + ' (' + formatPct(p.marginPct) + ')',
      '• Variación de contribución vs. venta habitual: ' + fmt(p.diffContribution),
      ''
    ];

    if (p.isTargetPriceMode) {
      lines.push(
        'PRECIO MÍNIMO SEGÚN MARGEN DESEADO',
        '• Margen de contribución deseado: ' + formatPct(p.targetMarginPct),
        '• Comisión sobre venta considerada: ' + formatPct(p.commissionPct),
        '• Tarifa mínima requerida: ' + (p.isPossible ? fmt(p.requiredPrice) : 'Inalcanzable (Margen + Comisiones >= 100%)'),
        '• Descuento máximo compatible: ' + (p.isPossible ? formatPct(p.maxCompatibleDiscountPct) : '—'),
        ''
      );
    }

    if (p.items && p.items.length > 0) {
      lines.push('DESGLOSE DE SERVICIOS EN EL COMBO:');
      p.items.forEach((it, idx) => {
        lines.push('  ' + (idx + 1) + '. ' + it.name + ': ' + it.quantity + 'x ' + fmt(it.price) + ' (Costo: ' + fmt(it.cost) + ')');
      });
      lines.push('');
    }

    lines.push(
      'INTERPRETACIÓN COMERCIAL',
      p.interpretacion || 'La contribución monetaria representa el dinero que queda tras cubrir costos directos para absorber gastos fijos. Un margen positivo no garantiza que la promoción sea aconsejable sin conocer demanda y capacidad.',
      '',
      'Informe generado por Gloss & Growth · glossgrowthhq.com'
    );

    return lines.join('\n');
  }

  function generatePromoPdf(data = {}) {
    const doc = createPdfDoc();
    const bName = data.businessName ? data.businessName.trim() : 'Tu Clínica o Spa';
    const dateObj = data.date || new Date();
    const dateStr = formatDate(dateObj);
    const filename = buildFilename('Simulacion_Promocion', bName, dateObj);
    const cur = data.currency || (typeof root !== 'undefined' && root.GlossCurrency ? root.GlossCurrency.getSelectedCurrency() : 'COP');
    const fmt = (v) => formatCurrency(v, cur);
    const p = data.promo || {};

    drawPdfHeader(doc, 'Simulación de Precios y Promociones', bName, dateStr, 'Modalidad: ' + (p.modalityTitle || 'Promoción') + ' · Tratamiento: ' + (p.treatmentName || 'Procedimiento'), cur);

    let curY = 41;

    curY = drawKpiGrid(doc, curY, [
      { label: 'Tarifa promocional', value: fmt(p.promoPrice), sub: 'Ahorro cliente: ' + fmt(p.savings) + ' (' + formatPct(p.discountPct) + ')' },
      { label: 'Costos variables', value: fmt(p.totalVarCost), sub: 'Insumos + honorarios + comisiones' },
      { label: 'Margen contribución', value: fmt(p.contribution), sub: formatPct(p.marginPct) + ' del precio promo' },
      { label: 'Variación vs habitual', value: fmt(p.diffContribution), sub: p.diffContribution < 0 ? 'Menor contribución unitaria' : 'Mayor o igual contribución' }
    ]);

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...C_CHARCOAL);
    doc.text('1. COMPARATIVA: TARIFA HABITUAL VS. ESTRATEGIA PROMOCIONAL', 15, curY + 2);
    curY += 4.5;

    const compRows = [
      ['Precio de venta al público (PVP):', fmt(p.regularPrice), fmt(p.promoPrice), fmt(p.promoPrice - p.regularPrice)],
      ['Costos variables directos totales:', fmt(p.regularVarCost), fmt(p.totalVarCost), fmt(p.totalVarCost - p.regularVarCost)],
      ['MARGEN DE CONTRIBUCIÓN DIRECTO:', fmt(p.regularContribution), fmt(p.contribution), fmt(p.diffContribution)],
      ['Margen de contribución (%):', formatPct(p.regularMarginPct), formatPct(p.marginPct), formatPct(p.marginPct - p.regularMarginPct)],
      ['Ahorro total para el cliente:', '$0', fmt(p.savings), formatPct(p.discountPct) + ' dcto.']
    ];

    doc.setFillColor(...C_BURGUNDY);
    doc.rect(15, curY, 180, 4.8, 'F');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(6.8);
    doc.setTextColor(...C_WHITE);
    doc.text('Concepto Evaluado', 18, curY + 3.4);
    doc.text('Tarifa Habitual', 105, curY + 3.4);
    doc.text('Oferta Promocional', 140, curY + 3.4);
    doc.text('Variación Neta', 172, curY + 3.4);
    curY += 4.8;

    compRows.forEach((row, idx) => {
      const isTotal = idx === 2;
      const isAlt = idx % 2 === 1;
      doc.setFillColor(isTotal ? 250 : (isAlt ? 249 : 255), isTotal ? 248 : (isAlt ? 248 : 255), isTotal ? 242 : (isAlt ? 246 : 255));
      doc.rect(15, curY, 180, 4.6, 'F');
      doc.setDrawColor(...C_CREAM_BORDER);
      doc.setLineWidth(0.15);
      doc.line(15, curY + 4.6, 195, curY + 4.6);

      doc.setFont('helvetica', isTotal ? 'bold' : 'normal');
      doc.setFontSize(6.8);
      doc.setTextColor(isTotal ? C_BURGUNDY[0] : C_CHARCOAL[0], isTotal ? C_BURGUNDY[1] : C_CHARCOAL[1], isTotal ? C_BURGUNDY[2] : C_CHARCOAL[2]);
      doc.text(row[0], 18, curY + 3.2);
      doc.text(row[1], 105, curY + 3.2);
      doc.text(row[2], 140, curY + 3.2);
      doc.text(row[3], 172, curY + 3.2);
      curY += 4.6;
    });

    curY += 3;

    curY = drawSectionCallout(doc, curY, '2. INTERPRETACIÓN COMERCIAL Y FINANCIERA', [
      { label: 'Hecho matemático:', text: p.hecho || ('La promoción genera una contribución de ' + fmt(p.contribution) + ' (' + formatPct(p.marginPct) + ' del precio ofertado).') },
      { label: 'Qué significa para el negocio:', text: p.significado || 'Ese excedente monetario debe contribuir a cubrir gastos fijos y marketing de la clínica.' },
      { label: 'Revisión recomendada:', text: p.recomendacion || 'Un margen de contribución positivo no garantiza que la promoción sea aconsejable si deteriora el ticket promedio sin compensar con mayor volumen u ocupación de cabinas.' }
    ]);

    drawPdfFooter(doc, 1, 1);
    return saveOrOutput(doc, filename);
  }

