  function generateBusinessBreakevenClipboard(data) {
    const bName = data.businessName ? data.businessName.trim() : 'Tu Clínica o Spa';
    const dateStr = formatDateShort(data.date || new Date());
    const cur = data.currency || (typeof root !== 'undefined' && root.GlossCurrency ? root.GlossCurrency.getSelectedCurrency() : 'COP');
    const curInfo = typeof root !== 'undefined' && root.GlossCurrency ? root.GlossCurrency.getCurrency(cur) : { name: cur, symbol: '$' };
    const fmt = (v) => formatCurrency(v, cur);
    const b = data.breakeven || {};

    let lines = [
      'GLOSS & GROWTH',
      'PUNTO DE EQUILIBRIO DEL NEGOCIO Y RESULTADO OPERATIVO',
      '',
      'Negocio: ' + bName,
      'Período analizado: Mensual',
      'Fecha: ' + dateStr,
      'Moneda: ' + curInfo.name + ' (' + cur + ')',
      '',
      'RESUMEN FINANCIERO Y COMPROMISOS DEL PERÍODO',
      '• Gastos fijos operativos mensuales: ' + fmt(b.fixedCosts),
      '• Costos de marketing del período: ' + fmt(b.marketingCosts) + ' (Pauta: ' + fmt(b.adSpend) + ' | Gestión: ' + fmt(b.agencyFee) + (b.agencyIncludedInFixed ? ' [incluida en fijos]' : '') + ')',
      '• Total gastos a cubrir por contribución: ' + fmt(b.totalCostsToCover),
      '• Margen de contribución global ponderado: ' + formatPct(b.marginPct),
      '',
      'PUNTO DE EQUILIBRIO',
      '• Facturación mensual mínima requerida: ' + fmt(b.breakevenRevenue)
    ];

    if (b.appointmentsBreakeven) {
      lines.push('• Atenciones estimadas requeridas para equilibrio: ' + formatInteger(b.appointmentsBreakeven) + ' citas (Ticket: ' + fmt(b.averageTicket) + ')');
    }

    lines.push(
      '',
      'SITUACIÓN ACTUAL DECLARADA',
      '• Facturación mensual declarada: ' + fmt(b.currentRevenue),
      '• Margen de contribución generado: ' + fmt(b.currentContribution),
      '• Resultado operativo estimado tras gastos: ' + fmt(b.estimatedResult),
      '• Diferencia frente al punto de equilibrio: ' + fmt(b.diffBreakeven),
      ''
    );

    if (b.targetResult > 0) {
      lines.push(
        'OBJETIVO EMPRESARIAL',
        '• Meta de resultado operativo mensual: ' + fmt(b.targetResult),
        '• Facturación requerida para alcanzar la meta: ' + fmt(b.targetRevenue),
        '• Diferencia frente a facturación actual: ' + fmt(b.diffTarget)
      );
      if (b.appointmentsTarget) {
        lines.push('• Atenciones requeridas para la meta: ' + formatInteger(b.appointmentsTarget) + ' citas');
      }
      lines.push('');
    }

    lines.push(
      'INTERPRETACIÓN DE RESULTADOS',
      b.interpretacion || 'El punto de equilibrio determina los ingresos indispensables para cubrir costos variables, fijos y marketing del período analizado. No sustituye estados financieros contables completos ni proyecciones de flujo de caja.',
      '',
      'Informe generado por Gloss & Growth · glossgrowthhq.com'
    );

    return lines.join('\n');
  }

  function generateBusinessBreakevenPdf(data = {}) {
    const doc = createPdfDoc();
    const bName = data.businessName ? data.businessName.trim() : 'Tu Clínica o Spa';
    const dateObj = data.date || new Date();
    const dateStr = formatDate(dateObj);
    const filename = buildFilename('Punto_Equilibrio_Negocio', bName, dateObj);
    const cur = data.currency || (typeof root !== 'undefined' && root.GlossCurrency ? root.GlossCurrency.getSelectedCurrency() : 'COP');
    const fmt = (v) => formatCurrency(v, cur);
    const b = data.breakeven || {};

    drawPdfHeader(doc, 'Punto de Equilibrio del Negocio', bName, dateStr, 'Análisis de absorción de gastos fijos operativos, marketing y facturación meta', cur);

    let curY = 41;

    curY = drawKpiGrid(doc, curY, [
      { label: 'Facturación de equilibrio', value: fmt(b.breakevenRevenue), sub: b.appointmentsBreakeven ? ('~' + formatInteger(b.appointmentsBreakeven) + ' atenciones est.') : 'Mínimo para no perder' },
      { label: 'Total gastos a cubrir', value: fmt(b.totalCostsToCover), sub: 'Fijos: ' + fmt(b.fixedCosts) + ' · Mkt: ' + fmt(b.marketingCosts) },
      { label: 'Margen contribución global', value: formatPct(b.marginPct), sub: 'Margen medio ponderado' },
      { label: 'Resultado operativo actual', value: fmt(b.estimatedResult), sub: b.diffBreakeven >= 0 ? 'Por encima de equilibrio' : 'Déficit operativo estimado' }
    ]);

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...C_CHARCOAL);
    doc.text('1. GASTOS FIJOS OPERATIVOS Y MARKETING DEL PERÍODO', 15, curY + 2);
    curY += 4.5;

    const fb = b.fixedBreakdown || {};
    const costRows = [
      ['Arriendo o alquiler de sede:', fmt(fb.rent || 0), 'Gastos Fijos Operativos'],
      ['Nómina fija mensual:', fmt(fb.payroll || 0), 'Gastos Fijos Operativos'],
      ['Servicios públicos y administración:', fmt((fb.utilities || 0) + (fb.admin || 0)), 'Gastos Fijos Operativos'],
      ['Software, suscripciones y otros fijos:', fmt((fb.software || 0) + (fb.other || 0)), 'Gastos Fijos Operativos'],
      ['SUBTOTAL GASTOS FIJOS OPERATIVOS (F):', fmt(b.fixedCosts), 'Compromiso estructural'],
      ['Inversión en pauta publicitaria (A):', fmt(b.adSpend), 'Marketing del período'],
      ['Honorarios agencia o gestión (G):', fmt(b.agencyFee), b.agencyIncludedInFixed ? 'Ya contemplado en fijos' : 'Marketing del período'],
      ['Otros gastos de marketing (O):', fmt(b.otherMarketing), 'Marketing del período'],
      ['TOTAL GASTOS DEL PERÍODO A CUBRIR (T):', fmt(b.totalCostsToCover), 'Fijos + Marketing']
    ];

    doc.setFillColor(...C_BURGUNDY);
    doc.rect(15, curY, 180, 4.8, 'F');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(6.8);
    doc.setTextColor(...C_WHITE);
    doc.text('Rubro de Gasto / Inversión', 18, curY + 3.4);
    doc.text('Importe Mensual', 125, curY + 3.4);
    doc.text('Clasificación', 165, curY + 3.4);
    curY += 4.8;

    costRows.forEach((row, idx) => {
      const isSub = idx === 4;
      const isTotal = idx === 8;
      const isAlt = idx % 2 === 1;
      doc.setFillColor((isTotal || isSub) ? 250 : (isAlt ? 249 : 255), (isTotal || isSub) ? 248 : (isAlt ? 248 : 255), (isTotal || isSub) ? 242 : (isAlt ? 246 : 255));
      doc.rect(15, curY, 180, 4.4, 'F');
      doc.setDrawColor(...C_CREAM_BORDER);
      doc.setLineWidth(0.15);
      doc.line(15, curY + 4.4, 195, curY + 4.4);

      doc.setFont('helvetica', (isTotal || isSub) ? 'bold' : 'normal');
      doc.setFontSize(6.5);
      doc.setTextColor((isTotal || isSub) ? C_BURGUNDY[0] : C_CHARCOAL[0], (isTotal || isSub) ? C_BURGUNDY[1] : C_CHARCOAL[1], (isTotal || isSub) ? C_BURGUNDY[2] : C_CHARCOAL[2]);
      doc.text(row[0], 18, curY + 3.1);
      doc.text(row[1], 125, curY + 3.1);
      doc.text(row[2], 165, curY + 3.1);
      curY += 4.4;
    });

    curY += 3;

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...C_CHARCOAL);
    doc.text('2. ESCENARIOS DE SENSIBILIDAD DEL NEGOCIO', 15, curY + 2);
    curY += 4.5;

    const scenarios = b.scenarios || [
      { label: '75% del equilibrio', revenue: b.breakevenRevenue * 0.75, operatingResult: -0.25 * b.totalCostsToCover },
      { label: '100% (Punto de Equilibrio)', revenue: b.breakevenRevenue, operatingResult: 0, isBreakeven: true },
      { label: '125% del equilibrio', revenue: b.breakevenRevenue * 1.25, operatingResult: 0.25 * b.totalCostsToCover },
      { label: '150% del equilibrio', revenue: b.breakevenRevenue * 1.50, operatingResult: 0.50 * b.totalCostsToCover }
    ];

    doc.setFillColor(...C_BURGUNDY);
    doc.rect(15, curY, 180, 4.8, 'F');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(6.8);
    doc.setTextColor(...C_WHITE);
    doc.text('Escenario Analizado', 18, curY + 3.4);
    doc.text('Facturación', 75, curY + 3.4);
    doc.text('Costos Variables', 110, curY + 3.4);
    doc.text('Contribución', 145, curY + 3.4);
    doc.text('Resultado Operativo', 172, curY + 3.4);
    curY += 4.8;

    scenarios.forEach((sc, idx) => {
      const isAlt = idx % 2 === 1;
      const isB = sc.isBreakeven;
      const mRatio = (b.marginPct || 60) / 100;
      const vc = sc.revenue * (1 - mRatio);
      const ct = sc.revenue * mRatio;

      doc.setFillColor(isB ? 250 : (isAlt ? 249 : 255), isB ? 248 : (isAlt ? 248 : 255), isB ? 242 : (isAlt ? 246 : 255));
      doc.rect(15, curY, 180, 4.4, 'F');
      doc.setDrawColor(...C_CREAM_BORDER);
      doc.setLineWidth(0.15);
      doc.line(15, curY + 4.4, 195, curY + 4.4);

      doc.setFont('helvetica', isB ? 'bold' : 'normal');
      doc.setFontSize(6.5);
      doc.setTextColor(isB ? C_BURGUNDY[0] : C_CHARCOAL[0], isB ? C_BURGUNDY[1] : C_CHARCOAL[1], isB ? C_BURGUNDY[2] : C_CHARCOAL[2]);
      doc.text(sc.label, 18, curY + 3.1);
      doc.text(fmt(sc.revenue), 75, curY + 3.1);
      doc.text(fmt(vc), 110, curY + 3.1);
      doc.text(fmt(ct), 145, curY + 3.1);
      doc.text(fmt(sc.operatingResult), 172, curY + 3.1);
      curY += 4.4;
    });

    curY += 3;

    curY = drawSectionCallout(doc, curY, '3. INTERPRETACIÓN FINANCIERA Y OPERATIVA', [
      { label: 'Hecho matemático:', text: b.hecho || ('El negocio requiere facturar ' + fmt(b.breakevenRevenue) + ' al mes con un margen del ' + formatPct(b.marginPct) + ' para absorber ' + fmt(b.totalCostsToCover) + ' de gastos fijos y marketing.') },
      { label: 'Qué significa para el negocio:', text: b.significado || (b.diffBreakeven >= 0 ? 'La facturación declarada cubre la estructura de costos y deja un resultado positivo.' : 'La contribución mensual no alcanza a cubrir la totalidad de los gastos fijos y marketing incluidos.') },
      { label: 'Revisión recomendada:', text: b.recomendacion || 'Evalúa si tu capacidad instalada soporta la meta de atenciones requerida y si la estructura de fijos es sostenible.' }
    ]);

    drawPdfFooter(doc, 1, 1);
    return saveOrOutput(doc, filename);
  }

