  // =========================================================================
  // 11. GENERADOR DE REPORTES: INVERSIÓN EN APARATOLOGÍA
  // =========================================================================

  function generateAparatologiaClipboard(data) {
    const bName = data.businessName ? data.businessName.trim() : 'Tu Clínica o Spa';
    const dateStr = formatDateShort(data.date || new Date());
    const cur = data.currency || (typeof root !== 'undefined' && root.GlossCurrency ? root.GlossCurrency.getSelectedCurrency() : 'COP');
    const curInfo = typeof root !== 'undefined' && root.GlossCurrency ? root.GlossCurrency.getCurrency(cur) : { name: cur, symbol: '$' };
    const fmt = (v) => formatCurrency(v, cur);
    const ap = data.aparatologia || {};

    let lines = [
      'GLOSS & GROWTH',
      'EVALUACIÓN DE INVERSIÓN EN APARATOLOGÍA ESTÉTICA',
      '',
      'Negocio: ' + bName,
      'Equipo: ' + (ap.equipmentName || 'Aparatología evaluada'),
      'Modalidad: ' + (ap.acquisitionModeTitle || ap.acquisitionMode || 'Compra de contado'),
      'Fecha: ' + dateStr,
      'Moneda: ' + curInfo.name + ' (' + cur + ')',
      '',
      'CONDICIONES DE ADQUISICIÓN Y FINANCIACIÓN',
      '• Precio de compra del equipo: ' + fmt(ap.equipmentPrice),
      '• Desembolso inicial (cuota inicial + instalación + capacitación): ' + fmt(ap.downPayment),
      '• Principal financiado: ' + fmt(ap.financedPrincipal),
      '• Cuota mensual de financiación / canon: ' + fmt(ap.monthlyFinancePayment),
      '• Intereses totales calculados: ' + fmt(ap.totalFinanceInterest),
      '• Costo total de adquisición del equipo: ' + fmt(ap.totalAcquisitionCost),
      '',
      'OPERACIÓN CLÍNICA Y RENTABILIDAD MENSUAL',
      '• Tratamiento vinculado: ' + (ap.treatmentName || 'Sesión con equipo'),
      '• Precio por sesión: ' + fmt(ap.pricePerSession),
      '• Costo variable por sesión: ' + fmt(ap.variableCostPerSession),
      '• Margen de contribución unitario: ' + fmt(ap.contributionPerSession) + ' (' + formatPct(ap.marginPct) + ')',
      '• Sesiones estimadas al mes: ' + formatInteger(ap.monthlySessions),
      '• Facturación mensual estimada: ' + fmt(ap.monthlyRevenue),
      '• Contribución mensual total: ' + fmt(ap.monthlyContribution),
      '• Mantenimiento y gastos fijos del equipo: ' + fmt(ap.totalIncrementalFixed),
      '• Resultado operativo antes de deuda: ' + fmt(ap.operatingResultBeforeFinance),
      '• Flujo de caja neto mensual tras pagos financieros: ' + fmt(ap.netCashFlowAfterFinance),
      '',
      'PUNTOS DE EQUILIBRIO Y RECUPERACIÓN (PAYBACK)',
      '• Sesiones/mes para cubrir costos del equipo: ' + formatInteger(ap.breakevenSessionsFixed) + ' sesiones',
      '• Sesiones/mes para cubrir equipo y servicio de deuda: ' + formatInteger(ap.breakevenSessionsWithFinance) + ' sesiones',
      '• Plazo de recuperación de la inversión total (Payback simple): ' + (ap.simplePaybackFormatted || '—'),
      '• Plazo de recuperación del capital inicial aportado (Equity Payback): ' + (ap.equityPaybackFormatted || '—')
    ];

    if (ap.demandScenarios && ap.demandScenarios.length) {
      lines.push('', 'ESCENARIOS DE DEMANDA Y SENSIBILIDAD');
      ap.demandScenarios.forEach(s => {
        lines.push('• ' + s.label + ': ' + formatInteger(s.sessions) + ' sesiones | Facturación: ' + fmt(s.revenue) + ' | Flujo neto: ' + fmt(s.netCashFlow) + ' | Payback: ' + s.payback);
      });
    }

    if (ap.operationalViability) {
      const op = ap.operationalViability;
      lines.push(
        '',
        'VIABILIDAD OPERATIVA DEL EQUIPO (CAPACIDAD IMPORTADA)',
        '• Centro analizado: ' + (op.businessName || bName),
        '• Equipo evaluado: ' + (op.equipmentName || ap.equipmentName),
        '• Profesionales compatibles: ' + op.compatibleStaffCount + ' de ' + op.totalStaffCount + ' habilitados (' + op.compatibleStaffNames + ')',
        '• Cabinas compatibles: ' + op.compatibleCabinsCount + ' de ' + op.totalCabinsCount + ' habilitadas (' + op.compatibleCabinsNames + ')',
        '• Capacidad programable estimada: ' + formatInteger(op.programmableCapacity) + ' sesiones/mes',
        '• Demanda mensual prevista: ' + formatInteger(op.monthlyDemand) + ' sesiones/mes',
        '• Diferencia (demanda vs capacidad): ' + (op.monthlyDemand > op.programmableCapacity ? '+' : '') + formatInteger(op.monthlyDemand - op.programmableCapacity) + ' sesiones',
        '• Sesiones factibles del escenario: ' + formatInteger(op.feasibleSessions) + ' sesiones/mes',
        '• Restricción operativa principal: ' + (op.bottleneck || '—'),
        '• Desplazamiento de otros servicios: ' + (op.displacementText || 'No se registraron compromisos previos.')
      );
    }

    if (ap.interpretation) {
      lines.push(
        '',
        'DIAGNÓSTICO FINANCIERO Y PRUDENCIA OPERATIVA',
        '1. Hecho matemático: ' + (ap.interpretation.hecho || '—'),
        '2. Significado para el negocio: ' + (ap.interpretation.significado || '—'),
        '3. Revisión recomendada: ' + (ap.interpretation.recomendacion || '—')
      );
    }

    lines.push('', 'Informe generado por Gloss & Growth · glossgrowthhq.com');
    return lines.join('\n');
  }

  function generateAparatologiaPdf(data = {}) {
    const doc = createPdfDoc();
    const bName = data.businessName ? data.businessName.trim() : 'Tu Clínica o Spa';
    const dateObj = data.date || new Date();
    const dateStr = formatDate(dateObj);
    const filename = buildFilename('Inversion_Aparatologia', bName, dateObj);
    const cur = data.currency || (typeof root !== 'undefined' && root.GlossCurrency ? root.GlossCurrency.getSelectedCurrency() : 'COP');
    const fmt = (v) => formatCurrency(v, cur);
    const ap = data.aparatologia || {};

    drawPdfHeader(doc, 'Inversión en Aparatología Estética', bName, dateStr, 'Evaluación de adquisición, financiación, operación clínica y plazo de recuperación', cur);

    let curY = 41;

    curY = drawKpiGrid(doc, curY, [
      { label: 'Costo total adquisición', value: fmt(ap.totalAcquisitionCost), sub: 'Inicial: ' + fmt(ap.downPayment) },
      { label: 'Cuota mensual / Canon', value: fmt(ap.monthlyFinancePayment), sub: ap.financedPrincipal > 0 ? ('Deuda: ' + fmt(ap.financedPrincipal)) : 'Sin cuota financiera' },
      { label: 'Flujo neto tras cuota', value: fmt(ap.netCashFlowAfterFinance), sub: 'Contribución: ' + fmt(ap.monthlyContribution) },
      { label: 'Recuperación capital propio', value: ap.equityPaybackFormatted || '—', sub: 'Payback total: ' + (ap.simplePaybackFormatted || '—') }
    ]);

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...C_CHARCOAL);
    doc.text('1. CONDICIONES FINANCIERAS Y OPERACIÓN CLÍNICA', 15, curY + 2);
    curY += 4.5;

    const opRows = [
      ['Equipo evaluado / Referencia:', ap.equipmentName || 'Aparatología', 'Identificación'],
      ['Modalidad de adquisición:', ap.acquisitionModeTitle || ap.acquisitionMode || 'Contado', 'Estructura contractual'],
      ['Desembolso inicial (Cuota inicial + Puesta en marcha):', fmt(ap.downPayment), 'Salida inicial de caja'],
      ['Tratamiento vinculado y precio por sesión:', (ap.treatmentName || 'Tratamiento') + ' (' + fmt(ap.pricePerSession) + ')', 'Operación en cabina'],
      ['Costo variable directo e insumos por sesión:', fmt(ap.variableCostPerSession), 'Costo variable'],
      ['Margen de contribución por sesión:', fmt(ap.contributionPerSession) + ' (' + formatPct(ap.marginPct) + ')', 'Excedente unitario'],
      ['Sesiones mensuales estimadas / Facturación:', formatInteger(ap.monthlySessions) + ' citas (' + fmt(ap.monthlyRevenue) + ')', 'Volumen esperado'],
      ['Mantenimiento periódico y costos fijos de equipo:', fmt(ap.totalIncrementalFixed), 'Fijo incremental'],
      ['Resultado operativo mensual (antes de deuda):', fmt(ap.operatingResultBeforeFinance), 'Rendimiento en cabina'],
      ['Flujo de caja libre mensual (después de cuota):', fmt(ap.netCashFlowAfterFinance), 'Liquidez neta'],
      ['Sesiones mínimas para cubrir costos y deuda:', formatInteger(ap.breakevenSessionsWithFinance) + ' citas/mes', 'Equilibrio operativo']
    ];

    doc.setFillColor(...C_BURGUNDY);
    doc.rect(15, curY, 180, 4.8, 'F');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(6.8);
    doc.setTextColor(...C_WHITE);
    doc.text('Parámetro Evaluado', 18, curY + 3.4);
    doc.text('Valor Calculado', 125, curY + 3.4);
    doc.text('Concepto Financiero', 165, curY + 3.4);
    curY += 4.8;

    opRows.forEach((row, idx) => {
      const isTotal = idx === 9;
      const isAlt = idx % 2 === 1;
      doc.setFillColor(isTotal ? 250 : (isAlt ? 249 : 255), isTotal ? 248 : (isAlt ? 248 : 255), isTotal ? 242 : (isAlt ? 246 : 255));
      doc.rect(15, curY, 180, 4.2, 'F');
      doc.setDrawColor(...C_CREAM_BORDER);
      doc.setLineWidth(0.15);
      doc.line(15, curY + 4.2, 195, curY + 4.2);

      doc.setFont('helvetica', isTotal ? 'bold' : 'normal');
      doc.setFontSize(6.4);
      doc.setTextColor(isTotal ? C_BURGUNDY[0] : C_CHARCOAL[0], isTotal ? C_BURGUNDY[1] : C_CHARCOAL[1], isTotal ? C_BURGUNDY[2] : C_CHARCOAL[2]);
      doc.text(row[0], 18, curY + 3.0);
      doc.text(row[1], 125, curY + 3.0);
      doc.text(row[2], 165, curY + 3.0);
      curY += 4.2;
    });

    curY += 3;

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...C_CHARCOAL);
    doc.text('2. SENSIBILIDAD POR ESCENARIOS DE DEMANDA', 15, curY + 2);
    curY += 4.5;

    const demandScenarios = ap.demandScenarios || [];
    doc.setFillColor(...C_BURGUNDY);
    doc.rect(15, curY, 180, 4.8, 'F');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(6.8);
    doc.setTextColor(...C_WHITE);
    doc.text('Nivel de Demanda', 18, curY + 3.4);
    doc.text('Sesiones/mes', 68, curY + 3.4);
    doc.text('Facturación', 98, curY + 3.4);
    doc.text('Flujo Neto', 135, curY + 3.4);
    doc.text('Recuperación', 168, curY + 3.4);
    curY += 4.8;

    demandScenarios.forEach((sc, idx) => {
      const isAlt = idx % 2 === 1;
      const isBase = idx === 1;
      doc.setFillColor(isBase ? 250 : (isAlt ? 249 : 255), isBase ? 248 : (isAlt ? 248 : 255), isBase ? 242 : (isAlt ? 246 : 255));
      doc.rect(15, curY, 180, 4.4, 'F');
      doc.setDrawColor(...C_CREAM_BORDER);
      doc.setLineWidth(0.15);
      doc.line(15, curY + 4.4, 195, curY + 4.4);

      doc.setFont('helvetica', isBase ? 'bold' : 'normal');
      doc.setFontSize(6.5);
      doc.setTextColor(...C_CHARCOAL);
      doc.text(sc.label, 18, curY + 3.1);
      doc.text(formatInteger(sc.sessions) + ' citas', 68, curY + 3.1);
      doc.text(fmt(sc.revenue), 98, curY + 3.1);
      doc.text((sc.netCashFlow >= 0 ? '+' : '') + fmt(sc.netCashFlow), 135, curY + 3.1);
      doc.text(sc.payback, 168, curY + 3.1);
      curY += 4.4;
    });

    curY += 3;

    const interp = ap.interpretation || {};

    if (ap.operationalViability) {
      const op = ap.operationalViability;
      const opItems = [
        { label: 'Capacidad programable mensual estimada:', text: `${formatInteger(op.programmableCapacity)} sesiones/mes (${op.compatibleStaffCount} de ${op.totalStaffCount} prof., ${op.compatibleCabinsCount} de ${op.totalCabinsCount} cabinas)` },
        { label: 'Demanda prevista vs. Factibles:', text: `Demanda: ${formatInteger(op.monthlyDemand)} citas/mes | Factibles proyectadas: ${formatInteger(op.feasibleSessions)} citas/mes` },
        { label: 'Restricción y cuello de botella:', text: op.bottleneck || 'Capacidad determinada por concurrencia de recursos.' },
        { label: 'Concurrencia y desplazamiento:', text: op.displacementText || 'No se registraron compromisos previos en agenda.' }
      ];
      curY = drawSectionCallout(doc, curY, '3. VIABILIDAD OPERATIVA Y CAPACIDAD INSTALADA', opItems);
      curY += 2;
    }

    const diagTitle = ap.operationalViability ? '4. DIAGNÓSTICO FINANCIERO Y PRUDENCIA' : '3. DIAGNÓSTICO FINANCIERO Y PRUDENCIA';
    curY = drawSectionCallout(doc, curY, diagTitle, [
      { label: 'Hecho matemático:', text: interp.hecho || 'Evaluación de viabilidad económica y cobertura de servicio de deuda.' },
      { label: 'Significado para el negocio:', text: interp.significado || 'Permite planificar compras de equipo sin comprometer la caja mensual.' },
      { label: 'Revisión recomendada:', text: interp.recomendacion || 'Verifica que la capacidad instalada y la agenda permitan absorber las sesiones proyectadas.' }
    ]);

    drawPdfFooter(doc, 1, 1);
    return saveOrOutput(doc, filename);
  }

  // =========================================================================
  // 11B. GENERADOR DE REPORTES: COMPARADOR FINANCIERO DE APARATOLOGÍA
  // =========================================================================

  function generateAparatologiaComparisonClipboard(data = {}) {
    const bName = data.businessName ? data.businessName.trim() : 'Tu Clínica o Spa';
    const dateStr = formatDateShort(data.date || new Date());
    const cur = data.currency || (typeof root !== 'undefined' && root.GlossCurrency ? root.GlossCurrency.getSelectedCurrency() : 'COP');
    const curInfo = typeof root !== 'undefined' && root.GlossCurrency ? root.GlossCurrency.getCurrency(cur) : { name: cur, symbol: '$' };
    const fmt = (v) => formatCurrency(v, cur);
    const comp = data.comparison || {};
    const modes = comp.activeModes || Object.keys(comp.results || {});
    const H = comp.horizonMonths || 24;

    const lines = [
      'GLOSS & GROWTH',
      'COMPARATIVA FINANCIERA DE APARATOLOGÍA ESTÉTICA',
      '',
      'Negocio: ' + bName,
      'Fecha: ' + dateStr,
      'Moneda: ' + curInfo.name + ' (' + cur + ')',
      'Horizonte evaluado: ' + H + ' meses',
      'Equipo evaluado: ' + (comp.equipmentName || 'Aparatología') + ' (Valor de compra ref: ' + fmt(comp.equipmentPrice || 0) + ')',
      '',
      'MODALIDADES COMPARADAS SIMULTÁNEAMENTE (' + modes.length + ' MODALIDADES):',
      '------------------------------------------------------------------------'
    ];

    modes.forEach(m => {
      const r = comp.results ? comp.results[m] : null;
      if (!r) return;
      lines.push(
        '► ' + (r.title || m).toUpperCase(),
        '  • Desembolso inicial de caja: ' + fmt(r.initialOutlay),
        '  • Cuota / compromiso mensual: ' + fmt(r.monthlyPayment) + (r.monthlyPaymentPost > 0 ? (' (continúa en ' + fmt(r.monthlyPaymentPost) + ')') : ' (luego $0)'),
        '  • Total pagado en ' + H + ' meses: ' + fmt(r.totalPaymentsInHorizon),
        '  • Sobrecosto financiero / intereses: ' + fmt(r.totalFinanceInterest),
        '  • Saldo de capital pendiente al mes ' + H + ': ' + fmt(r.remainingBalance),
        '  • Flujo neto de caja acumulado al mes ' + H + ': ' + fmt(r.cumulativeCashFlow),
        '  • Situación de propiedad: ' + r.ownershipStatus,
        r.contractAlert ? ('  • Alerta contractual: ' + r.contractAlert) : '',
        ''
      );
    });

    if (comp.highlights) {
      const h = comp.highlights;
      lines.push(
        'DESTACADOS DE LA COMPARATIVA (HORIZONTE ' + H + ' MESES):',
        h.lowestInitialOutlay ? ('• Menor barrera inicial de entrada: ' + h.lowestInitialOutlay.title + ' (' + fmt(h.lowestInitialOutlay.initialOutlay) + ')') : '',
        h.lowestMonthlyCommitment ? ('• Menor cuota mensual obligatoria: ' + h.lowestMonthlyCommitment.title + ' (' + fmt(h.lowestMonthlyCommitment.monthlyPayment) + ')') : '',
        h.lowestTotalPayments ? ('• Menor desembolso total acumulado: ' + h.lowestTotalPayments.title + ' (' + fmt(h.lowestTotalPayments.totalPaymentsInHorizon) + ')') : '',
        h.highestCumulativeCashFlow ? ('• Mayor excedente neto acumulado: ' + h.highestCumulativeCashFlow.title + ' (' + fmt(h.highestCumulativeCashFlow.cumulativeCashFlow) + ')') : '',
        ''
      );
    }

    if (comp.interpretation) {
      const it = comp.interpretation;
      lines.push(
        'EVALUACIÓN PRUDENTE Y CRITERIO FINANCIERO:',
        it.desembolso ? ('1. ' + it.desembolso) : '',
        it.pagos ? ('2. ' + it.pagos) : '',
        it.caja ? ('3. ' + it.caja) : '',
        it.prudencia ? ('4. ' + it.prudencia) : '',
        ''
      );
    }

    lines.push('Informe generado por Gloss & Growth · glossgrowthhq.com');
    return lines.filter(l => l !== '').join('\n');
  }

  function generateAparatologiaComparisonPdf(data = {}) {
    const doc = createPdfDoc();
    const bName = data.businessName ? data.businessName.trim() : 'Tu Clínica o Spa';
    const dateObj = data.date || new Date();
    const dateStr = formatDate(dateObj);
    const filename = buildFilename('Comparativa_Aparatologia', bName, dateObj);
    const cur = data.currency || (typeof root !== 'undefined' && root.GlossCurrency ? root.GlossCurrency.getSelectedCurrency() : 'COP');
    const fmt = (v) => formatCurrency(v, cur);
    const comp = data.comparison || {};
    const modes = comp.activeModes || Object.keys(comp.results || {});
    const H = comp.horizonMonths || 24;

    drawPdfHeader(doc, 'Comparativa de Adquisición de Aparatología', bName, dateStr, 'Evaluación financiera simultánea en horizonte uniforme de ' + H + ' meses', cur);

    let curY = 41;

    // Highlights KPI Grid
    const h = comp.highlights || {};
    const kpiItems = [
      {
        label: 'Menor entrada inicial',
        value: h.lowestInitialOutlay ? fmt(h.lowestInitialOutlay.initialOutlay) : '—',
        sub: h.lowestInitialOutlay ? h.lowestInitialOutlay.title : ''
      },
      {
        label: 'Menor cuota mensual',
        value: h.lowestMonthlyCommitment ? fmt(h.lowestMonthlyCommitment.monthlyPayment) : '—',
        sub: h.lowestMonthlyCommitment ? h.lowestMonthlyCommitment.title : ''
      },
      {
        label: 'Menor pago total (' + H + 'm)',
        value: h.lowestTotalPayments ? fmt(h.lowestTotalPayments.totalPaymentsInHorizon) : '—',
        sub: h.lowestTotalPayments ? h.lowestTotalPayments.title : ''
      },
      {
        label: 'Mayor flujo neto (' + H + 'm)',
        value: h.highestCumulativeCashFlow ? fmt(h.highestCumulativeCashFlow.cumulativeCashFlow) : '—',
        sub: h.highestCumulativeCashFlow ? h.highestCumulativeCashFlow.title : ''
      }
    ];

    curY = drawKpiGrid(doc, curY, kpiItems);

    // Section 1: Cuadro comparativo
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...C_CHARCOAL);
    doc.text('1. CUADRO COMPARATIVO MULTI-MODALIDAD (HORIZONTE ' + H + ' MESES)', 15, curY + 2);
    curY += 4.5;

    const labelColW = 50;
    const availW = 180 - labelColW;
    const colW = availW / Math.max(1, modes.length);

    // Header
    doc.setFillColor(...C_BURGUNDY);
    doc.rect(15, curY, 180, 5, 'F');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(6.8);
    doc.setTextColor(...C_WHITE);
    doc.text('Métrica / Modalidad', 17, curY + 3.5);

    modes.forEach((m, idx) => {
      const r = comp.results ? comp.results[m] : null;
      const title = r ? r.title : m;
      const x = 15 + labelColW + (idx * colW);
      doc.text(title, x + 1.5, curY + 3.5, { maxWidth: colW - 3 });
    });
    curY += 5;

    // Rows
    const rowsDef = [
      { label: 'Desembolso inicial (cuota 0 + gastos):', getValue: (r) => fmt(r.initialOutlay) },
      { label: 'Cuota / canon mensual pactado:', getValue: (r) => fmt(r.monthlyPayment) },
      { label: 'Total pagado en ' + H + ' meses:', getValue: (r) => fmt(r.totalPaymentsInHorizon), isHighlight: true },
      { label: 'Sobrecosto financiero / intereses:', getValue: (r) => fmt(r.totalFinanceInterest) },
      { label: 'Saldo de capital pendiente al mes ' + H + ':', getValue: (r) => fmt(r.remainingBalance) },
      { label: 'Flujo neto acumulado al mes ' + H + ':', getValue: (r) => fmt(r.cumulativeCashFlow), isHighlight: true },
      { label: 'Propiedad al mes ' + H + ':', getValue: (r) => r.id === 'alquiler' ? 'Arrendador (Sin prop.)' : (r.id === 'leasing' ? (r.isContractComplete ? 'Clínica (Opción ejer.)' : 'Banco (En leasing)') : 'Clínica (Propiedad)') }
    ];

    rowsDef.forEach((def, rIdx) => {
      const isAlt = rIdx % 2 === 1;
      const rowH = 4.3;
      doc.setFillColor(def.isHighlight ? 250 : (isAlt ? 249 : 255), def.isHighlight ? 248 : (isAlt ? 248 : 255), def.isHighlight ? 242 : (isAlt ? 246 : 255));
      doc.rect(15, curY, 180, rowH, 'F');
      doc.setDrawColor(...C_CREAM_BORDER);
      doc.setLineWidth(0.15);
      doc.line(15, curY + rowH, 195, curY + rowH);

      doc.setFont('helvetica', def.isHighlight ? 'bold' : 'normal');
      doc.setFontSize(6.2);
      doc.setTextColor(def.isHighlight ? C_BURGUNDY[0] : C_CHARCOAL[0], def.isHighlight ? C_BURGUNDY[1] : C_CHARCOAL[1], def.isHighlight ? C_BURGUNDY[2] : C_CHARCOAL[2]);
      doc.text(def.label, 17, curY + 3.0);

      modes.forEach((m, cIdx) => {
        const r = comp.results ? comp.results[m] : null;
        const val = r ? def.getValue(r) : '—';
        const x = 15 + labelColW + (cIdx * colW);
        doc.text(String(val), x + 1.5, curY + 3.0, { maxWidth: colW - 3 });
      });

      curY += rowH;
    });

    curY += 3.5;

    // Section 2: Interpretation Callout
    const it = comp.interpretation || {};
    const calloutItems = [];
    if (it.desembolso) calloutItems.push({ label: 'Barrera de entrada:', text: it.desembolso });
    if (it.pagos) calloutItems.push({ label: 'Desembolso en horizonte:', text: it.pagos });
    if (it.caja) calloutItems.push({ label: 'Impacto en liquidez:', text: it.caja });
    if (it.prudencia) calloutItems.push({ label: 'Criterio prudencial:', text: it.prudencia });

    if (calloutItems.length > 0) {
      curY = drawSectionCallout(doc, curY, '2. DIAGNÓSTICO FINANCIERO Y PRUDENCIA DE DECISIÓN', calloutItems);
    }

    drawPdfFooter(doc, 1, 1);
    return saveOrOutput(doc, filename);
  }

