  function generateCapacidadAvanzadaClipboard(data) {
    const bName = data.businessName ? data.businessName.trim() : 'Tu Clínica o Spa';
    const dateStr = formatDateShort(data.date || new Date());
    const cur = data.currency || (typeof root !== 'undefined' && root.GlossCurrency ? root.GlossCurrency.getSelectedCurrency() : 'COP');
    const curInfo = typeof root !== 'undefined' && root.GlossCurrency ? root.GlossCurrency.getCurrency(cur) : { name: cur, symbol: '$' };
    const fmt = (v) => formatCurrency(v, cur);
    const adv = data.result || {};

    let lines = [
      'GLOSS & GROWTH',
      'SIMULADOR DE CAPACIDAD INSTALADA AVANZADA (MULTI-RECURSOS)',
      '',
      'Negocio: ' + bName,
      'Fecha: ' + dateStr,
      'Moneda: ' + curInfo.name + ' (' + cur + ')',
      '',
      'CAPACIDAD OPERATIVA CONSOLIDADA',
      '• Capacidad diaria simultánea: ' + formatInteger(adv.dailyAppointments) + ' citas al día',
      '• Capacidad teórica mensual: ' + formatInteger(adv.monthlyCapacity) + ' citas (' + (adv.daysPerMonth || 22) + ' días)',
      '• Citas efectivas proyectadas (con ' + (adv.cancellationPct || 0) + '% inasistencias): ' + formatInteger(adv.effectiveAttended) + ' citas',
      '• Facturación potencial máxima estimada: ' + fmt(adv.monthlyPotentialRevenue),
      '• Restricción / Cuello de botella detectado: ' + (adv.bottleneck || 'Equilibrado')
    ];

    if (adv.packageSummary && adv.packageSummary.totalOriginalSessions > 0) {
      const ps = adv.packageSummary;
      lines.push(
        '',
        'CONTROL DE PAQUETES Y SESIONES PENDIENTES',
        '• Sesiones originales contratadas: ' + formatInteger(ps.totalOriginalSessions),
        '• Sesiones ya realizadas: ' + formatInteger(ps.completedSessions),
        '• Sesiones pendientes por atender: ' + formatInteger(ps.pendingSessions),
        '• Sesiones pendientes con reserva en agenda: ' + formatInteger(ps.bookedPendingSessions),
        '• Sesiones pendientes sin programar: ' + formatInteger(ps.unbookedPendingSessions)
      );
    }

    if (adv.treatmentsResults && adv.treatmentsResults.length) {
      lines.push('', 'DESGLOSE POR TRATAMIENTO');
      adv.treatmentsResults.forEach(t => {
        lines.push('• ' + t.name + ' (' + t.effectiveDuration + ' min efectivos): ' + formatInteger(t.dailyMaxAppointments) + ' citas/día | ' + formatInteger(t.monthlyMaxAppointments) + ' citas/mes (' + fmt(t.monthlyPotentialRevenue) + ')');
      });
    }

    lines.push('', 'Informe generado por Gloss & Growth · glossgrowthhq.com');
    return lines.join('\n');
  }

  function generateCapacidadAvanzadaPdf(data = {}) {
    const doc = createPdfDoc();
    const bName = data.businessName ? data.businessName.trim() : 'Tu Clínica o Spa';
    const dateObj = data.date || new Date();
    const dateStr = formatDate(dateObj);
    const filename = buildFilename('Capacidad_Avanzada', bName, dateObj);
    const cur = data.currency || (typeof root !== 'undefined' && root.GlossCurrency ? root.GlossCurrency.getSelectedCurrency() : 'COP');
    const fmt = (v) => formatCurrency(v, cur);
    const adv = data.result || {};

    drawPdfHeader(doc, 'Capacidad Instalada Avanzada', bName, dateStr, 'Simulación multi-tratamiento, horarios individuales, equipos y pausas', cur);

    let curY = 41;

    curY = drawKpiGrid(doc, curY, [
      { label: 'Capacidad diaria máx.', value: formatInteger(adv.dailyAppointments) + ' citas', sub: (adv.daysPerMonth || 22) + ' días/mes' },
      { label: 'Capacidad mensual', value: formatInteger(adv.monthlyCapacity) + ' citas', sub: 'Efectivas: ' + formatInteger(adv.effectiveAttended) },
      { label: 'Facturación potencial', value: fmt(adv.monthlyPotentialRevenue), sub: 'Al 100% capacidad' },
      { label: 'Restricción clave', value: 'Cuello botella', sub: adv.bottleneck || 'Equilibrado' }
    ]);

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...C_CHARCOAL);
    doc.text('1. RENDIMIENTO OPERATIVO POR TRATAMIENTO Y DURACIÓN', 15, curY + 2);
    curY += 4.5;

    const treatRows = (adv.treatmentsResults || []).map(t => [
      t.name,
      t.effectiveDuration + ' min',
      formatInteger(t.dailyMaxAppointments) + ' citas',
      formatInteger(t.monthlyMaxAppointments) + ' citas',
      fmt(t.monthlyPotentialRevenue)
    ]);

    doc.setFillColor(...C_BURGUNDY);
    doc.rect(15, curY, 180, 4.8, 'F');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(6.8);
    doc.setTextColor(...C_WHITE);
    doc.text('Tratamiento Evaluado', 18, curY + 3.4);
    doc.text('Duración Efectiva', 80, curY + 3.4);
    doc.text('Máx. Día', 115, curY + 3.4);
    doc.text('Máx. Mes', 140, curY + 3.4);
    doc.text('Facturación Potencial', 165, curY + 3.4);
    curY += 4.8;

    treatRows.forEach((row, idx) => {
      const isAlt = idx % 2 === 1;
      doc.setFillColor(isAlt ? 249 : 255, isAlt ? 248 : 255, isAlt ? 246 : 255);
      doc.rect(15, curY, 180, 4.4, 'F');
      doc.setDrawColor(...C_CREAM_BORDER);
      doc.setLineWidth(0.15);
      doc.line(15, curY + 4.4, 195, curY + 4.4);

      doc.setFont('helvetica', 'normal');
      doc.setFontSize(6.5);
      doc.setTextColor(...C_CHARCOAL);
      doc.text(row[0], 18, curY + 3.1);
      doc.text(row[1], 80, curY + 3.1);
      doc.text(row[2], 115, curY + 3.1);
      doc.text(row[3], 140, curY + 3.1);
      doc.text(row[4], 165, curY + 3.1);
      curY += 4.4;
    });

    curY += 3;

    if (adv.packageSummary && adv.packageSummary.totalOriginalSessions > 0) {
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(8.5);
      doc.setTextColor(...C_CHARCOAL);
      doc.text('2. CONTROL DE SESIONES Y PAQUETES EN CURSO', 15, curY + 2);
      curY += 4.5;

      const ps = adv.packageSummary;
      const packRows = [
        ['Total sesiones contratadas:', formatInteger(ps.totalOriginalSessions), 'Compromiso global'],
        ['Sesiones realizadas:', formatInteger(ps.completedSessions), 'Ejecutadas'],
        ['Sesiones pendientes:', formatInteger(ps.pendingSessions), 'Por atender'],
        ['Sesiones programadas en agenda:', formatInteger(ps.bookedPendingSessions), 'Con turno fijado'],
        ['Sesiones pendientes sin programar:', formatInteger(ps.unbookedPendingSessions), 'Compromiso latente']
      ];

      packRows.forEach((row, idx) => {
        const isAlt = idx % 2 === 1;
        doc.setFillColor(isAlt ? 249 : 255, isAlt ? 248 : 255, isAlt ? 246 : 255);
        doc.rect(15, curY, 180, 4.2, 'F');
        doc.setDrawColor(...C_CREAM_BORDER);
        doc.setLineWidth(0.15);
        doc.line(15, curY + 4.2, 195, curY + 4.2);

        doc.setFont('helvetica', idx === 4 ? 'bold' : 'normal');
        doc.setFontSize(6.4);
        doc.setTextColor(idx === 4 ? C_BURGUNDY[0] : C_CHARCOAL[0], idx === 4 ? C_BURGUNDY[1] : C_CHARCOAL[1], idx === 4 ? C_BURGUNDY[2] : C_CHARCOAL[2]);
        doc.text(row[0], 18, curY + 3.0);
        doc.text(row[1], 125, curY + 3.0);
        doc.text(row[2], 165, curY + 3.0);
        curY += 4.2;
      });

      curY += 3;
    }

    curY = drawSectionCallout(doc, curY, '3. ANÁLISIS DE CUELLOS DE BOTELLA Y RECURSOS', [
      { label: 'Restricción principal:', text: adv.bottleneck || 'Capacidad determinada por disponibilidad horaria de recursos.' },
      { label: 'Margen de inasistencias:', text: 'Se aplicó una tasa prudencial del ' + (adv.cancellationPct || 0) + '% de inasistencias o cancelaciones imprevistas sobre la agenda.' },
      { label: 'Recomendación operativa:', text: 'Vigila que los tiempos de desinfección y preparación no se omitan para garantizar seguridad clínica.' }
    ]);

    drawPdfFooter(doc, 1, 1);
    return saveOrOutput(doc, filename);
  }

