  function generateGuionReelPdf(scriptData = {}) {
    const doc = createPdfDoc();
    const bName = scriptData.businessName ? scriptData.businessName.trim() : 'Tu Clínica o Spa';
    const dateObj = scriptData.date || new Date();
    const dateStr = formatDate(dateObj);
    const treatmentName = scriptData.treatment_name || 'Tratamiento Estético';
    const structName = scriptData.structure_name || 'Estructura Narrativa';
    const filename = buildFilename('Guion-Reel', treatmentName.replace(/[^a-zA-Z0-9]/g, '-'), dateObj);

    drawPdfHeader(doc, 'Guion Técnico de Rodaje (Reel)', bName, dateStr, `${treatmentName} · Estructura: ${structName}`, 'COP');

    let curY = 41;

    // Resumen del Rodaje
    const summaryItems = [
      { label: 'Estructura y Enfoque:', text: `${structName} · Tono: ${scriptData.tone || 'Clínico y prudente'}` },
      { label: 'Duración Estimada:', text: `${scriptData.estimated_duration || '45-60 segundos'} (~${scriptData.total_words || 130} palabras)` },
      { label: 'Recursos en Cabina:', text: scriptData.props_summary || 'Bata médica, instrumental estéril, iluminación neutra' },
      { label: 'Objetivo y CTA:', text: scriptData.cta_summary || 'Agendamiento de valoración clínica presencial' }
    ];

    curY = drawSectionCallout(doc, curY, '1. FICHA TÉCNICA DE PRODUCCIÓN', summaryItems);
    curY += 4;

    // Apertura de impacto (0-3s)
    if (scriptData.hook_opening) {
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(8.5);
      doc.setTextColor(...C_CHARCOAL);
      doc.text('2. APERTURA DE IMPACTO (0-3 SEGUNDOS)', 15, curY + 2);
      curY += 5;

      const hookItems = [
        { label: 'Texto en pantalla:', text: scriptData.hook_opening.textual || '' },
        { label: 'Gancho hablado:', text: `"${scriptData.hook_opening.verbal || ''}"` },
        { label: 'Acción visual (0-2s):', text: scriptData.hook_opening.visual || '' }
      ];
      curY = drawSectionCallout(doc, curY, null, hookItems);
      curY += 4;
    }

    // Desglose de Beats
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...C_CHARCOAL);
    doc.text('3. DESGLOSE DE BEATS SEGUNDO A SEGUNDO', 15, curY + 2);
    curY += 5;

    let pageNum = 1;
    const beats = Array.isArray(scriptData.beats) ? scriptData.beats : [];

    beats.forEach((b, idx) => {
      if (curY > 230) {
        drawPdfFooter(doc, pageNum, 2);
        doc.addPage();
        pageNum++;
        curY = 20;
      }

      // Beat Header Box
      doc.setFillColor(...C_CREAM_BG);
      doc.rect(15, curY, 180, 5, 'F');
      doc.setDrawColor(...C_CREAM_BORDER);
      doc.setLineWidth(0.2);
      doc.rect(15, curY, 180, 5, 'S');

      doc.setFont('helvetica', 'bold');
      doc.setFontSize(7);
      doc.setTextColor(...C_BURGUNDY);
      doc.text(`PASO ${b.beat_number || idx + 1}: ${b.role ? b.role.toUpperCase() : ''}`, 18, curY + 3.5);

      doc.setFont('helvetica', 'normal');
      doc.setFontSize(6.5);
      doc.setTextColor(...C_CHARCOAL);
      doc.text(`Tiempo: ${b.timecode || ''}`, 150, curY + 3.5);
      curY += 6;

      // Cues
      const camSplit = doc.splitTextToSize(`Cámara: ${b.camera_cue || ''}`, 174);
      const audioSplit = doc.splitTextToSize(`Guion hablado: "${b.teleprompter_text || ''}"`, 174);
      const textSplit = doc.splitTextToSize(`Texto pantalla: ${b.screen_overlay || ''}`, 174);

      doc.setFont('helvetica', 'italic');
      doc.setFontSize(6.2);
      doc.setTextColor(...C_MUTED);
      camSplit.forEach(line => {
        doc.text(line, 18, curY + 2.5);
        curY += 3.2;
      });

      doc.setFont('helvetica', 'normal');
      doc.setFontSize(6.5);
      doc.setTextColor(...C_CHARCOAL);
      audioSplit.forEach(line => {
        doc.text(line, 18, curY + 2.5);
        curY += 3.4;
      });

      if (b.screen_overlay) {
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(6.2);
        doc.setTextColor(...C_BURGUNDY);
        textSplit.forEach(line => {
          doc.text(line, 18, curY + 2.5);
          curY += 3.2;
        });
      }

      curY += 3;
    });

    // Advertencia legal / checklist
    if (scriptData.regulatory_notice || scriptData.shooting_checklist) {
      if (curY > 235) {
        drawPdfFooter(doc, pageNum, pageNum + 1);
        doc.addPage();
        pageNum++;
        curY = 20;
      }
      const finalItems = [];
      if (scriptData.shooting_checklist) finalItems.push({ label: 'Checklist de rodaje:', text: scriptData.shooting_checklist });
      if (scriptData.regulatory_notice) finalItems.push({ label: 'Marco legal y sanitario:', text: scriptData.regulatory_notice });
      curY = drawSectionCallout(doc, curY, '4. REQUERIMIENTOS Y CUMPLIMIENTO SANITARIO', finalItems);
    }

    drawPdfFooter(doc, pageNum, pageNum);
    return saveOrOutput(doc, filename);
  }

