  function generateCalendarClipboard(events, options = {}) {
    const bName = options.businessName || 'Tu Clínica o Spa';
    const period = options.period || 'Cronograma Editorial';
    const lines = [
      '================================================================',
      `GLOSS & GROWTH — PLANIFICACIÓN EDITORIAL (${period.toUpperCase()})`,
      '================================================================',
      `Fecha de exportación: ${formatDateIso(new Date())}`,
      bName ? `Negocio / Clínica: ${bName}` : '',
      `Total de publicaciones programadas: ${(events || []).length}`,
      '----------------------------------------------------------------',
      ''
    ].filter(Boolean);

    const formatLabels = {
      reel: 'Reel (Video corto)',
      carrusel: 'Carrusel (Educativo)',
      historia: 'Historia (Interacción)',
      anuncio: 'Anuncio Publicitario (Ad)'
    };

    const statusLabels = {
      pendiente: 'Pendiente',
      por_grabar: 'Por grabar',
      en_edicion: 'En edición',
      listo: 'Listo para publicar',
      publicado: 'Publicado'
    };

    if (!events || events.length === 0) {
      lines.push('No hay publicaciones programadas en este período.');
    } else {
      events.forEach((evt, idx) => {
        lines.push(`[${idx + 1}] ${evt.date || 'Sin fecha'} ${evt.time ? '· ' + evt.time : ''}`);
        lines.push(`    Formato: ${formatLabels[evt.type] || evt.type || 'Contenido'}`);
        lines.push(`    Título: ${evt.title}`);
        if (evt.treatment_name) lines.push(`    Tratamiento: ${evt.treatment_name}`);
        lines.push(`    Estado: ${statusLabels[evt.status] || evt.status || 'Pendiente'}`);
        if (evt.hook_verbal) lines.push(`    Gancho verbal: "${evt.hook_verbal}"`);
        if (evt.notes) lines.push(`    Notas de rodaje / copy: ${evt.notes}`);
        lines.push('');
      });
    }

    lines.push('----------------------------------------------------------------');
    lines.push('Cumplimiento normativo: Verifique Resolución 3100 de 2019 y Ley 711 de 2001.');
    lines.push('Generado con Estudio de Contenido — Gloss & Growth');

    return lines.join('\n');
  }

  function generateCalendarPdf(events, options = {}) {
    const doc = createPdfDoc();
    const bName = options.businessName ? options.businessName.trim() : 'Tu Clínica o Spa';
    const period = options.period || 'Planificación Editorial';
    const dateStr = formatDate(new Date());
    const filename = buildFilename('Cronograma-Editorial', (options.monthKey || 'mensual'));

    drawPdfHeader(
      doc,
      'CRONOGRAMA EDITORIAL Y PLANIFICACIÓN',
      bName,
      dateStr,
      `Calendario de publicaciones (${period})`
    );

    let curY = 41;

    const formatCounts = { reel: 0, carrusel: 0, historia: 0, anuncio: 0 };
    const statusCounts = { pendiente: 0, por_grabar: 0, en_edicion: 0, listo: 0, publicado: 0 };

    (events || []).forEach(e => {
      if (formatCounts[e.type] !== undefined) formatCounts[e.type]++;
      if (statusCounts[e.status] !== undefined) statusCounts[e.status]++;
    });

    const kpiItems = [
      {
        label: 'Total publicaciones',
        value: String((events || []).length),
        sub: 'En el período'
      },
      {
        label: 'Reels / Video corto',
        value: String(formatCounts.reel),
        sub: 'Formato dinámico'
      },
      {
        label: 'Carruseles / Post',
        value: String(formatCounts.carrusel + formatCounts.anuncio),
        sub: `${formatCounts.carrusel} carr. · ${formatCounts.anuncio} ads`
      },
      {
        label: 'Listos / Publicados',
        value: String(statusCounts.listo + statusCounts.publicado),
        sub: `${statusCounts.por_grabar + statusCounts.en_edicion} en producción`
      }
    ];

    curY = drawKpiGrid(doc, curY, kpiItems);

    // Section 1: Tabla de publicaciones
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...C_CHARCOAL);
    doc.text('1. CRONOGRAMA DE PUBLICACIONES Y ESTADO DE PRODUCCIÓN', 15, curY + 2);
    curY += 5;

    // Table Header
    doc.setFillColor(...C_BURGUNDY);
    doc.rect(15, curY, 180, 5, 'F');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(6.8);
    doc.setTextColor(...C_WHITE);
    doc.text('Fecha / Hora', 17, curY + 3.5);
    doc.text('Formato', 40, curY + 3.5);
    doc.text('Título y Tratamiento', 68, curY + 3.5);
    doc.text('Gancho / Notas', 130, curY + 3.5);
    doc.text('Estado', 175, curY + 3.5);
    curY += 5;

    let pageNum = 1;
    const items = events || [];

    if (items.length === 0) {
      doc.setFillColor(...C_CREAM_BG);
      doc.rect(15, curY, 180, 8, 'F');
      doc.setFont('helvetica', 'italic');
      doc.setFontSize(7);
      doc.setTextColor(...C_MUTED);
      doc.text('No hay publicaciones programadas para este período.', 18, curY + 5);
      curY += 10;
    } else {
      items.forEach((evt, idx) => {
        if (curY > 240) {
          drawPdfFooter(doc, pageNum, 2);
          doc.addPage();
          pageNum++;
          curY = 20;

          // Repeat table header on new page
          doc.setFillColor(...C_BURGUNDY);
          doc.rect(15, curY, 180, 5, 'F');
          doc.setFont('helvetica', 'bold');
          doc.setFontSize(6.8);
          doc.setTextColor(...C_WHITE);
          doc.text('Fecha / Hora', 17, curY + 3.5);
          doc.text('Formato', 40, curY + 3.5);
          doc.text('Título y Tratamiento', 68, curY + 3.5);
          doc.text('Gancho / Notas', 130, curY + 3.5);
          doc.text('Estado', 175, curY + 3.5);
          curY += 5;
        }

        const isAlt = idx % 2 === 1;
        const rowH = 7.5;
        doc.setFillColor(isAlt ? 249 : 255, isAlt ? 248 : 255, isAlt ? 246 : 255);
        doc.rect(15, curY, 180, rowH, 'F');
        doc.setDrawColor(...C_CREAM_BORDER);
        doc.setLineWidth(0.15);
        doc.line(15, curY + rowH, 195, curY + rowH);

        doc.setFont('helvetica', 'bold');
        doc.setFontSize(6.2);
        doc.setTextColor(...C_CHARCOAL);
        doc.text(evt.date || '—', 17, curY + 3.2);
        doc.setFont('helvetica', 'normal');
        doc.setFontSize(5.5);
        doc.setTextColor(...C_MUTED);
        doc.text(evt.time || '10:00', 17, curY + 6.2);

        // Formato
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(6);
        const fmtColor = evt.type === 'reel' ? C_BURGUNDY : (evt.type === 'anuncio' ? [6, 95, 70] : [30, 58, 138]);
        doc.setTextColor(...fmtColor);
        doc.text((evt.type || 'reel').toUpperCase(), 40, curY + 4.5);

        // Título + tratamiento
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(6.2);
        doc.setTextColor(...C_CHARCOAL);
        const titleStr = doc.splitTextToSize(evt.title || 'Sin título', 58);
        doc.text(titleStr[0] || '', 68, curY + 3.2);
        doc.setFont('helvetica', 'normal');
        doc.setFontSize(5.5);
        doc.setTextColor(...C_MUTED);
        doc.text(evt.treatment_name || 'General', 68, curY + 6.2);

        // Gancho / Notas
        doc.setFont('helvetica', 'normal');
        doc.setFontSize(5.8);
        doc.setTextColor(...C_CHARCOAL);
        const noteStr = doc.splitTextToSize(evt.hook_verbal || evt.notes || '—', 42);
        doc.text(noteStr[0] || '—', 130, curY + 4.5);

        // Estado
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(5.8);
        const statusColors = {
          pendiente: [120, 110, 105],
          por_grabar: [154, 52, 18],
          en_edicion: [124, 58, 237],
          listo: [22, 101, 52],
          publicado: [30, 58, 138]
        };
        const sCol = statusColors[evt.status] || [120, 110, 105];
        doc.setTextColor(...sCol);
        const sLabel = (evt.status || 'pendiente').replace('_', ' ').toUpperCase();
        doc.text(sLabel, 175, curY + 4.5);

        curY += rowH;
      });
    }

    curY += 4;
    curY = drawSectionCallout(
      doc,
      curY,
      'AVISO DE CUMPLIMIENTO SANITARIO Y PUBLICITARIO (COLOMBIA)',
      [
        {
          label: 'Marco normativo y ético:',
          text: 'Todo contenido publicado por clínicas o profesionales de la salud debe ajustarse a la Resolución 3100 de 2019 del Ministerio de Salud y la Ley 711 de 2001. Está prohibido inducir a error, garantizar resultados infalibles o publicar fotografías de antes y después engañosas.'
        }
      ]
    );

    drawPdfFooter(doc, pageNum, pageNum);
    return saveOrOutput(doc, filename);
  }

