  function generateCarouselClipboard(carousel = {}) {
    const title = carousel.title || 'Carrusel Educativo';
    const treat = carousel.treatment_name || 'Procedimiento Estético';
    const arch = carousel.archetype_name || 'Arquetipo';
    const slides = carousel.slides || [];

    let out = `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
    out += `GLOSS & GROWTH · ESTRUCTURA EDITORIAL DE CARRUSEL\n`;
    out += `Título: ${title}\n`;
    out += `Tratamiento: ${treat} · Arquetipo: ${arch}\n`;
    out += `Total láminas: ${slides.length} diapositivas (Formato 4:5 / 1080x1350)\n`;
    out += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n`;

    slides.forEach((s, idx) => {
      out += `[SLIDE ${idx + 1} / ${slides.length}] Rol: ${s.role || 'DESARROLLO'}\n`;
      out += `📌 TÍTULO: ${s.title || 'Sin título'}\n`;
      out += `📝 COPY: ${s.copy_text || s.copy || 'Sin texto'}\n`;
      out += `🎨 DIRECCIÓN VISUAL: ${s.visual_guidance || s.visual_layout || 'Sin guía'}\n`;
      if (s.micro_hook) out += `👉 Micro-gancho: "${s.micro_hook}"\n`;
      out += `\n`;
    });

    out += `⚖️ CUMPLIMIENTO SANITARIO:\n`;
    out += `${carousel.regulatory_warning || 'Cumplimiento Resolución 3100 de 2019 / Ley 711 de 2001. Habilitación REPS requerida.'}\n`;
    out += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
    out += `Generado por Estudio de Contenido de Gloss & Growth · https://glossgrowthhq.com\n`;
    return out;
  }

